#[derive(Clone, Copy, Debug)]
enum DynamicHcsTailPolicy {
    MeasuredEntropy,
    FixedBlocks(f64),
}

fn dynamic_hcs_tail_policy() -> Result<DynamicHcsTailPolicy, String> {
    match std::env::var("KRASIS_DYNAMIC_HCS_TAIL_BLOCKS") {
        Ok(raw) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() || trimmed.eq_ignore_ascii_case("auto") {
                return Ok(DynamicHcsTailPolicy::MeasuredEntropy);
            }
            match trimmed.parse::<f64>() {
                Ok(v) if v.is_finite() && v > 0.0 => Ok(DynamicHcsTailPolicy::FixedBlocks(v)),
                _ => Err(format!(
                    "KRASIS_DYNAMIC_HCS_TAIL_BLOCKS={} is invalid; expected 'auto' or a positive finite block count",
                    raw,
                )),
            }
        }
        Err(_) => Ok(DynamicHcsTailPolicy::MeasuredEntropy),
    }
}

fn populate_measured_heatmap_flat(
    heatmap_flat: &mut [u64],
    layer_expert_counts: &[Option<usize>],
    num_experts_per_layer: usize,
    measured_counts: &[(usize, usize, u64)],
) -> Result<usize, String> {
    if num_experts_per_layer == 0 {
        return Err("measured heatmap import requires a nonzero expert stride".to_string());
    }
    let required_slots = layer_expert_counts
        .len()
        .checked_mul(num_experts_per_layer)
        .ok_or_else(|| "measured heatmap shape overflow".to_string())?;
    if heatmap_flat.len() != required_slots {
        return Err(format!(
            "measured heatmap storage has {} slots; expected {} layers x {} experts = {}",
            heatmap_flat.len(),
            layer_expert_counts.len(),
            num_experts_per_layer,
            required_slots,
        ));
    }

    heatmap_flat.fill(0);
    let mut seen = std::collections::HashSet::with_capacity(measured_counts.len());
    let mut imported = 0usize;
    for &(layer_idx, expert_idx, count) in measured_counts {
        let Some(Some(layer_experts)) = layer_expert_counts.get(layer_idx) else {
            return Err(format!(
                "measured heatmap route L{}E{} does not name a registered MoE layer",
                layer_idx, expert_idx,
            ));
        };
        if expert_idx >= *layer_experts {
            return Err(format!(
                "measured heatmap route L{}E{} exceeds the layer's {} experts",
                layer_idx, expert_idx, layer_experts,
            ));
        }
        if !seen.insert((layer_idx, expert_idx)) {
            return Err(format!(
                "measured heatmap contains duplicate route L{}E{}",
                layer_idx, expert_idx,
            ));
        }
        let flat_idx = layer_idx
            .checked_mul(num_experts_per_layer)
            .and_then(|base| base.checked_add(expert_idx))
            .ok_or_else(|| "measured heatmap index overflow".to_string())?;
        heatmap_flat[flat_idx] = count;
        imported += 1;
    }
    Ok(imported)
}

fn measured_entropy_dynamic_tail_mask(
    layer_slots: &[Vec<usize>],
    slot_to_expert: &[Option<(usize, usize)>],
    heatmap_flat: &[u64],
    num_experts_per_layer: usize,
    loaded_slots: usize,
    slot_capacity: usize,
) -> Result<Vec<bool>, String> {
    if loaded_slots > slot_capacity || loaded_slots > slot_to_expert.len() {
        return Err(format!(
            "loaded slot count {} exceeds tail geometry (capacity={}, mappings={})",
            loaded_slots,
            slot_capacity,
            slot_to_expert.len(),
        ));
    }
    if num_experts_per_layer == 0 {
        return Err("measured dynamic HCS tail requires a nonzero expert stride".to_string());
    }

    let mut evictable = vec![false; slot_capacity];
    let mut registered = vec![false; loaded_slots];
    let mut active_layers = 0usize;
    let mut marked = 0usize;
    for (layer_idx, slots) in layer_slots.iter().enumerate() {
        let mut measured = Vec::new();
        for &slot in slots {
            if slot >= loaded_slots {
                continue;
            }
            if registered[slot] {
                return Err(format!("loaded slot {} is registered more than once", slot));
            }
            registered[slot] = true;
            let Some((mapped_layer, expert_idx)) = slot_to_expert[slot] else {
                return Err(format!("loaded slot {} has no expert mapping", slot));
            };
            if mapped_layer != layer_idx || expert_idx >= num_experts_per_layer {
                return Err(format!(
                    "loaded slot {} maps to L{}E{} but is registered under layer {}",
                    slot, mapped_layer, expert_idx, layer_idx,
                ));
            }
            let heatmap_idx = mapped_layer
                .checked_mul(num_experts_per_layer)
                .and_then(|base| base.checked_add(expert_idx))
                .ok_or_else(|| "dynamic HCS heatmap index overflow".to_string())?;
            let count = heatmap_flat.get(heatmap_idx).copied().unwrap_or(0);
            measured.push((slot, count));
        }
        if measured.is_empty() {
            continue;
        }
        active_layers += 1;
        let total: u64 = measured.iter().map(|(_, count)| *count).sum();
        if total == 0 {
            return Err(format!(
                "measured dynamic HCS tail has no route mass for active layer {}",
                layer_idx,
            ));
        }
        let total_f = total as f64;
        let entropy = measured
            .iter()
            .filter_map(|(_, count)| {
                if *count == 0 {
                    None
                } else {
                    let probability = *count as f64 / total_f;
                    Some(-probability * probability.ln())
                }
            })
            .sum::<f64>();
        let effective_support = entropy.exp();
        if !effective_support.is_finite() || effective_support <= 0.0 {
            return Err(format!(
                "measured dynamic HCS tail produced invalid effective support {} for layer {}",
                effective_support, layer_idx,
            ));
        }
        let protected = (effective_support.ceil() as usize).min(measured.len());
        let tail = measured.len().saturating_sub(protected).max(1);
        measured.sort_by(|(slot_a, count_a), (slot_b, count_b)| {
            count_a.cmp(count_b).then_with(|| slot_b.cmp(slot_a))
        });
        for &(slot, _) in measured.iter().take(tail.min(measured.len())) {
            evictable[slot] = true;
            marked += 1;
        }
    }
    let registered_slots = registered.iter().filter(|&&value| value).count();
    if registered_slots != loaded_slots {
        return Err(format!(
            "layer map covers {} of {} loaded slots",
            registered_slots, loaded_slots,
        ));
    }
    if active_layers == 0 || marked < active_layers {
        return Err(format!(
            "measured dynamic HCS tail marked {} slots across {} active layers",
            marked, active_layers,
        ));
    }
    Ok(evictable)
}

fn layer_balanced_dynamic_tail_mask(
    layer_slots: &[Vec<usize>],
    loaded_slots: usize,
    slot_capacity: usize,
    requested_tail_slots: usize,
) -> Result<Vec<bool>, String> {
    let mut evictable = vec![false; slot_capacity];
    let target = requested_tail_slots.min(loaded_slots).min(slot_capacity);
    if target == 0 {
        return Ok(evictable);
    }
    if loaded_slots > slot_capacity {
        return Err(format!(
            "loaded slot count {} exceeds slot capacity {}",
            loaded_slots, slot_capacity,
        ));
    }

    let mut registered = vec![false; slot_capacity];
    let mut registered_slots = 0usize;
    let mut active_layers = 0usize;
    for slots in layer_slots {
        let mut layer_active = false;
        for &slot in slots {
            if slot >= loaded_slots {
                continue;
            }
            if registered[slot] {
                return Err(format!("loaded slot {} is registered more than once", slot));
            }
            registered[slot] = true;
            registered_slots += 1;
            layer_active = true;
        }
        active_layers += usize::from(layer_active);
    }
    if registered_slots != loaded_slots {
        return Err(format!(
            "layer map covers {} of {} loaded slots",
            registered_slots, loaded_slots,
        ));
    }
    if active_layers == 0 {
        return Err(format!(
            "nonzero tail target {} has no active layer mapping",
            target,
        ));
    }
    if target < active_layers {
        return Err(format!(
            "tail target {} cannot cover all {} active layers",
            target, active_layers,
        ));
    }

    let base = target / active_layers;
    let remainder = target % active_layers;
    let mut active_rank = 0usize;
    let mut marked = 0usize;
    for slots in layer_slots {
        let available = slots
            .iter()
            .filter(|&&slot| slot < loaded_slots && slot < slot_capacity)
            .count();
        if available == 0 {
            continue;
        }
        let quota = base + usize::from(active_rank < remainder);
        active_rank += 1;
        for &slot in slots
            .iter()
            .rev()
            .filter(|&&slot| slot < loaded_slots && slot < slot_capacity)
            .take(quota.min(available))
        {
            if !evictable[slot] {
                evictable[slot] = true;
                marked += 1;
            }
        }
    }

    // A layer can contain fewer resident slots than its equal-share quota.
    // Preserve the measured total tail size by assigning any remainder to the
    // globally lowest-priority unmarked slots after every active layer has had
    // its opportunity. This is deterministic and never exceeds loaded HCS.
    if marked < target {
        for slot in (0..loaded_slots).rev() {
            if registered[slot] && !evictable[slot] {
                evictable[slot] = true;
                marked += 1;
                if marked == target {
                    break;
                }
            }
        }
    }
    if marked != target {
        return Err(format!(
            "layer-balanced allocation marked {} of {} requested tail slots",
            marked, target,
        ));
    }
    Ok(evictable)
}

#[cfg(test)]
mod dynamic_tail_tests {
    use super::{
        layer_balanced_dynamic_tail_mask, measured_entropy_dynamic_tail_mask,
        populate_measured_heatmap_flat, HcsState,
    };

    #[test]
    fn measured_heatmap_counts_are_imported_at_runtime_layer_indices() {
        let mut flat = vec![99; 12];
        let imported = populate_measured_heatmap_flat(
            &mut flat,
            &[None, Some(4), Some(3)],
            4,
            &[(1, 2, 17), (2, 0, 11), (2, 2, 5)],
        )
        .unwrap();
        assert_eq!(imported, 3);
        assert_eq!(flat, vec![0, 0, 0, 0, 0, 0, 17, 0, 11, 0, 5, 0]);
    }

    #[test]
    fn measured_heatmap_import_rejects_non_moe_and_duplicate_routes() {
        let mut flat = vec![0; 8];
        let non_moe = populate_measured_heatmap_flat(&mut flat, &[None, Some(4)], 4, &[(0, 0, 1)])
            .unwrap_err();
        assert_eq!(
            non_moe,
            "measured heatmap route L0E0 does not name a registered MoE layer"
        );

        let duplicate =
            populate_measured_heatmap_flat(&mut flat, &[None, Some(4)], 4, &[(1, 2, 1), (1, 2, 2)])
                .unwrap_err();
        assert_eq!(duplicate, "measured heatmap contains duplicate route L1E2");
    }

    #[test]
    fn tail_is_balanced_across_layers_instead_of_using_a_global_suffix() {
        let layers = vec![
            vec![0, 1, 2, 3, 4, 5],
            vec![6, 7, 8, 9, 10],
            vec![11, 12, 13, 14, 15],
        ];
        let mask = layer_balanced_dynamic_tail_mask(&layers, 16, 16, 6).unwrap();
        assert_eq!(mask.iter().filter(|&&value| value).count(), 6);
        for slots in &layers {
            assert_eq!(
                slots.iter().filter(|&&slot| mask[slot]).count(),
                2,
                "every active layer must receive its equal-share tail"
            );
        }
    }

    #[test]
    fn short_layer_remainder_is_reassigned_without_changing_tail_size() {
        let layers = vec![vec![0], vec![1, 2, 3, 4, 5], vec![6, 7, 8, 9, 10]];
        let mask = layer_balanced_dynamic_tail_mask(&layers, 11, 11, 6).unwrap();
        assert_eq!(mask.iter().filter(|&&value| value).count(), 6);
        assert!(mask[0], "a short active layer must remain evictable");
        assert!(layers[1].iter().any(|&slot| mask[slot]));
        assert!(layers[2].iter().any(|&slot| mask[slot]));
    }

    #[test]
    fn incomplete_layer_mapping_is_rejected_instead_of_falling_back() {
        let layers = vec![vec![0, 1], vec![3, 4]];
        let error = layer_balanced_dynamic_tail_mask(&layers, 5, 5, 4).unwrap_err();
        assert_eq!(error, "layer map covers 4 of 5 loaded slots");
    }

    #[test]
    fn undersized_tail_is_rejected_instead_of_skipping_layers() {
        let layers = vec![vec![0], vec![1], vec![2]];
        let error = layer_balanced_dynamic_tail_mask(&layers, 3, 3, 2).unwrap_err();
        assert_eq!(error, "tail target 2 cannot cover all 3 active layers");
    }

    #[test]
    fn measured_tail_uses_per_layer_effective_route_support() {
        let layers = vec![vec![0, 1, 2, 3], vec![4, 5, 6, 7]];
        let mappings = vec![
            Some((0, 0)),
            Some((0, 1)),
            Some((0, 2)),
            Some((0, 3)),
            Some((1, 0)),
            Some((1, 1)),
            Some((1, 2)),
            Some((1, 3)),
        ];
        let heatmap = vec![90, 10, 0, 0, 25, 25, 25, 25];
        let mask =
            measured_entropy_dynamic_tail_mask(&layers, &mappings, &heatmap, 4, 8, 8).unwrap();

        // L0 has effective support ~=1.38, so two experts are protected and
        // the two zero-mass experts form the dynamic tail. Uniform L1 has
        // effective support four, so only its structural one-slot tail is
        // exposed.
        assert_eq!(
            mask,
            vec![false, false, true, true, false, false, false, true]
        );
    }

    #[test]
    fn measured_tail_is_scale_invariant() {
        let layers = vec![vec![0, 1, 2, 3]];
        let mappings = vec![Some((0, 0)), Some((0, 1)), Some((0, 2)), Some((0, 3))];
        let a = measured_entropy_dynamic_tail_mask(&layers, &mappings, &[50, 30, 15, 5], 4, 4, 4)
            .unwrap();
        let b = measured_entropy_dynamic_tail_mask(
            &layers,
            &mappings,
            &[5000, 3000, 1500, 500],
            4,
            4,
            4,
        )
        .unwrap();
        assert_eq!(a, b);
    }

    #[test]
    fn measured_tail_rejects_missing_route_evidence() {
        let layers = vec![vec![0, 1]];
        let mappings = vec![Some((0, 0)), Some((0, 1))];
        let error =
            measured_entropy_dynamic_tail_mask(&layers, &mappings, &[0, 0], 2, 2, 2).unwrap_err();
        assert_eq!(
            error,
            "measured dynamic HCS tail has no route mass for active layer 0"
        );
    }

    #[test]
    fn collection_interval_reset_preserves_dynamic_tail_route_evidence() {
        let mut hcs = HcsState::new();
        hcs.num_experts_per_layer = 4;
        hcs.init_cache_fast(1);
        hcs.heatmap_flat.copy_from_slice(&[90, 10, 0, 0]);
        hcs.dynamic_tail_route_counts_flat
            .copy_from_slice(&hcs.heatmap_flat);

        hcs.start_collection_interval();

        assert_eq!(hcs.heatmap_flat, vec![0, 0, 0, 0]);
        assert_eq!(hcs.dynamic_tail_route_counts_flat, vec![90, 10, 0, 0]);
        let mask = measured_entropy_dynamic_tail_mask(
            &[vec![0, 1, 2, 3]],
            &[Some((0, 0)), Some((0, 1)), Some((0, 2)), Some((0, 3))],
            &hcs.dynamic_tail_route_counts_flat,
            4,
            4,
            4,
        )
        .unwrap();
        assert_eq!(mask, vec![false, false, true, true]);
    }
}

fn bind_hcs_route_pointer_device(device: &Arc<CudaDevice>, reason: &str) -> bool {
    if let Err(e) = device.bind_to_thread() {
        log::error!(
            "GPU route sync: failed to bind CUDA device before HCS pointer-table update ({}): {:?}",
            reason,
            e,
        );
        false
    } else {
        true
    }
}

#[derive(Clone, Default)]
struct RouteLocalityLayerStats {
    selected: u64,
    last1_hits: u64,
    actual_hcs_hits: u64,
    heatmap_hits: Vec<u64>,
    lru_hits: Vec<u64>,
    heatmap_lru_hits: Vec<u64>,
    decayed_lfu_hits: Vec<u64>,
    adaptive_hits: Vec<u64>,
}

#[derive(Clone)]
struct RouteLocalityCoverageState {
    heatmap_hits: u64,
    lru_hits: u64,
    heatmap_lru_hits: u64,
    decayed_lfu_hits: u64,
    adaptive_hits: u64,
    lru_by_layer: Vec<Vec<i32>>,
    heatmap_lru_by_layer: Vec<Vec<i32>>,
    lfu_scores_by_layer: Vec<Vec<f32>>,
    adaptive_lru_by_split_layer: Vec<Vec<Vec<i32>>>,
    adaptive_score_by_split_layer: Vec<Vec<f64>>,
}

impl RouteLocalityCoverageState {
    fn new(split_count: usize) -> Self {
        Self {
            heatmap_hits: 0,
            lru_hits: 0,
            heatmap_lru_hits: 0,
            decayed_lfu_hits: 0,
            adaptive_hits: 0,
            lru_by_layer: Vec::new(),
            heatmap_lru_by_layer: Vec::new(),
            lfu_scores_by_layer: Vec::new(),
            adaptive_lru_by_split_layer: vec![Vec::new(); split_count],
            adaptive_score_by_split_layer: vec![Vec::new(); split_count],
        }
    }

    fn reset_counts(&mut self) {
        self.heatmap_hits = 0;
        self.lru_hits = 0;
        self.heatmap_lru_hits = 0;
        self.decayed_lfu_hits = 0;
        self.adaptive_hits = 0;
        self.lru_by_layer.clear();
        self.heatmap_lru_by_layer.clear();
        self.lfu_scores_by_layer.clear();
        for split in self.adaptive_lru_by_split_layer.iter_mut() {
            split.clear();
        }
        for split in self.adaptive_score_by_split_layer.iter_mut() {
            split.clear();
        }
    }

    fn ensure_layer(&mut self, layer_idx: usize, num_experts: usize) {
        if self.lru_by_layer.len() <= layer_idx {
            self.lru_by_layer.resize_with(layer_idx + 1, Vec::new);
        }
        if self.heatmap_lru_by_layer.len() <= layer_idx {
            self.heatmap_lru_by_layer
                .resize_with(layer_idx + 1, Vec::new);
        }
        if self.lfu_scores_by_layer.len() <= layer_idx {
            self.lfu_scores_by_layer
                .resize_with(layer_idx + 1, Vec::new);
        }
        if self.lfu_scores_by_layer[layer_idx].len() != num_experts {
            self.lfu_scores_by_layer[layer_idx] = vec![0.0; num_experts];
        }
        for split in self.adaptive_lru_by_split_layer.iter_mut() {
            if split.len() <= layer_idx {
                split.resize_with(layer_idx + 1, Vec::new);
            }
        }
        for split in self.adaptive_score_by_split_layer.iter_mut() {
            if split.len() <= layer_idx {
                split.resize(layer_idx + 1, 0.0);
            }
        }
    }
}

#[derive(Clone)]
struct RouteLocalityStats {
    enabled: bool,
    coverage_pcts: Vec<f64>,
    heatmap_pin_pct: f64,
    route_events: u64,
    selected_total: u64,
    last1_hits: u64,
    actual_hcs_hits: u64,
    actual_hcs_cached: usize,
    actual_hcs_possible: usize,
    previous_by_layer: Vec<Vec<i32>>,
    heatmap_rank_by_layer: Vec<Vec<usize>>,
    policy_states: Vec<RouteLocalityCoverageState>,
    global_lru_states: Vec<RouteLocalityGlobalLruState>,
    layer_stats: Vec<RouteLocalityLayerStats>,
}

#[derive(Clone)]
struct RouteLocalityGlobalLruState {
    capacity: usize,
    hits: u64,
    cache: Vec<u64>,
}

impl RouteLocalityGlobalLruState {
    fn new(capacity: usize) -> Self {
        Self {
            capacity,
            hits: 0,
            cache: Vec::with_capacity(capacity),
        }
    }

    fn reset(&mut self) {
        self.hits = 0;
        self.cache.clear();
    }

    fn record(&mut self, layer_idx: usize, selected: &[i32]) {
        let keys: Vec<u64> = selected
            .iter()
            .copied()
            .filter(|&expert_idx| expert_idx >= 0)
            .map(|expert_idx| ((layer_idx as u64) << 32) | expert_idx as u32 as u64)
            .collect();
        self.hits += keys.iter().filter(|key| self.cache.contains(*key)).count() as u64;
        for key in keys.into_iter().rev() {
            if let Some(position) = self.cache.iter().position(|cached| *cached == key) {
                self.cache.remove(position);
            }
            self.cache.insert(0, key);
            if self.cache.len() > self.capacity {
                self.cache.truncate(self.capacity);
            }
        }
    }
}

impl RouteLocalityStats {
    fn from_env() -> Self {
        let enabled = env_truthy("KRASIS_ROUTE_LOCALITY");
        let coverage_pcts = env_f64_list(
            "KRASIS_ROUTE_LOCALITY_COVERAGE_PCTS",
            ROUTE_LOCALITY_DEFAULT_COVERAGE_PCTS,
        );
        let policy_count = coverage_pcts.len();
        let split_count = ROUTE_LOCALITY_ADAPTIVE_SPLITS.len();
        let global_lru_capacities = env_usize_list("KRASIS_ROUTE_LOCALITY_TOTAL_CAPACITIES");
        let s = Self {
            enabled,
            coverage_pcts,
            heatmap_pin_pct: ROUTE_LOCALITY_HEATMAP_PIN_PCT,
            route_events: 0,
            selected_total: 0,
            last1_hits: 0,
            actual_hcs_hits: 0,
            actual_hcs_cached: 0,
            actual_hcs_possible: 0,
            previous_by_layer: Vec::new(),
            heatmap_rank_by_layer: Vec::new(),
            policy_states: (0..policy_count)
                .map(|_| RouteLocalityCoverageState::new(split_count))
                .collect(),
            global_lru_states: global_lru_capacities
                .into_iter()
                .map(RouteLocalityGlobalLruState::new)
                .collect(),
            layer_stats: Vec::new(),
        };
        if enabled {
            log::info!(
                "Route locality diagnostic enabled: coverage_pcts={:?}, heatmap_pin_pct={:.1}, lfu_decay={:.3}, adaptive_splits={:?}, global_lru_capacities={:?}",
                s.coverage_pcts,
                s.heatmap_pin_pct,
                ROUTE_LOCALITY_LFU_DECAY,
                ROUTE_LOCALITY_ADAPTIVE_SPLITS,
                s.global_lru_states
                    .iter()
                    .map(|state| state.capacity)
                    .collect::<Vec<_>>(),
            );
        }
        s
    }

    fn reset_counts(&mut self) {
        self.route_events = 0;
        self.selected_total = 0;
        self.last1_hits = 0;
        self.actual_hcs_hits = 0;
        self.actual_hcs_cached = 0;
        self.actual_hcs_possible = 0;
        self.previous_by_layer.clear();
        self.heatmap_rank_by_layer.clear();
        for state in self.policy_states.iter_mut() {
            state.reset_counts();
        }
        for state in self.global_lru_states.iter_mut() {
            state.reset();
        }
        self.layer_stats.clear();
    }

    fn ensure_layer(&mut self, layer_idx: usize, num_experts: usize) {
        if self.previous_by_layer.len() <= layer_idx {
            self.previous_by_layer.resize_with(layer_idx + 1, Vec::new);
        }
        if self.heatmap_rank_by_layer.len() <= layer_idx {
            self.heatmap_rank_by_layer
                .resize_with(layer_idx + 1, Vec::new);
        }
        if self.layer_stats.len() <= layer_idx {
            self.layer_stats
                .resize_with(layer_idx + 1, RouteLocalityLayerStats::default);
        }
        let policy_count = self.coverage_pcts.len();
        if self.layer_stats[layer_idx].heatmap_hits.len() < policy_count {
            self.layer_stats[layer_idx]
                .heatmap_hits
                .resize(policy_count, 0);
        }
        if self.layer_stats[layer_idx].lru_hits.len() < policy_count {
            self.layer_stats[layer_idx].lru_hits.resize(policy_count, 0);
        }
        if self.layer_stats[layer_idx].heatmap_lru_hits.len() < policy_count {
            self.layer_stats[layer_idx]
                .heatmap_lru_hits
                .resize(policy_count, 0);
        }
        if self.layer_stats[layer_idx].decayed_lfu_hits.len() < policy_count {
            self.layer_stats[layer_idx]
                .decayed_lfu_hits
                .resize(policy_count, 0);
        }
        if self.layer_stats[layer_idx].adaptive_hits.len() < policy_count {
            self.layer_stats[layer_idx]
                .adaptive_hits
                .resize(policy_count, 0);
        }
        for state in self.policy_states.iter_mut() {
            state.ensure_layer(layer_idx, num_experts);
        }
    }

    fn coverage_capacity(num_experts: usize, pct: f64) -> usize {
        if num_experts == 0 {
            0
        } else {
            ((num_experts as f64) * pct / 100.0).ceil().max(1.0) as usize
        }
    }

    fn update_lru(cache: &mut Vec<i32>, eid: i32, capacity: usize) {
        if capacity == 0 {
            cache.clear();
            return;
        }
        if let Some(pos) = cache.iter().position(|&v| v == eid) {
            cache.remove(pos);
        }
        cache.insert(0, eid);
        if cache.len() > capacity {
            cache.truncate(capacity);
        }
    }

    fn ensure_heatmap_rank(
        &mut self,
        layer_idx: usize,
        num_experts: usize,
        hcs: Option<&HcsState>,
    ) {
        if self.heatmap_rank_by_layer[layer_idx].len() == num_experts
            && self.heatmap_rank_by_layer[layer_idx]
                .iter()
                .any(|&rank| rank != usize::MAX)
        {
            return;
        }
        let mut ranks = vec![usize::MAX; num_experts];
        let Some(hcs) = hcs else {
            self.heatmap_rank_by_layer[layer_idx] = ranks;
            return;
        };
        if hcs.num_experts_per_layer == 0 {
            self.heatmap_rank_by_layer[layer_idx] = ranks;
            return;
        }
        let base = layer_idx.saturating_mul(hcs.num_experts_per_layer);
        let mut entries: Vec<(u64, usize)> = (0..num_experts)
            .map(|expert_idx| {
                let idx = base + expert_idx;
                let count = hcs.heatmap_flat.get(idx).copied().unwrap_or(0);
                (count, expert_idx)
            })
            .collect();
        if !entries.iter().any(|(count, _)| *count > 0) {
            let mut fill_from_order = |ordered: &[(usize, usize)]| -> usize {
                let mut layer_rank = ranks.iter().filter(|&&rank| rank != usize::MAX).count();
                for &(rank_layer, expert_idx) in ordered.iter() {
                    if rank_layer == layer_idx
                        && expert_idx < num_experts
                        && ranks[expert_idx] == usize::MAX
                    {
                        ranks[expert_idx] = layer_rank;
                        layer_rank += 1;
                    }
                }
                layer_rank
            };
            let mut filled = fill_from_order(&hcs.heatmap_ranking);
            if filled == 0 {
                filled = fill_from_order(&hcs.soft_heatmap_ranking);
            }
            if filled == 0 {
                filled = fill_from_order(&hcs.soft_ranking);
            }
            if filled == 0 {
                let pool_order: Vec<(usize, usize)> = hcs
                    .pool_slot_to_expert
                    .iter()
                    .filter_map(|slot| *slot)
                    .collect();
                fill_from_order(&pool_order);
            }
            self.heatmap_rank_by_layer[layer_idx] = ranks;
            return;
        }
        entries.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
        for (rank, (_, expert_idx)) in entries.into_iter().enumerate() {
            ranks[expert_idx] = rank;
        }
        self.heatmap_rank_by_layer[layer_idx] = ranks;
    }

    #[inline]
    fn heatmap_hit(heatmap_rank: &[usize], eid: i32, capacity: usize) -> bool {
        if capacity == 0 || eid < 0 {
            return false;
        }
        heatmap_rank
            .get(eid as usize)
            .copied()
            .map(|rank| rank < capacity)
            .unwrap_or(false)
    }

    fn lfu_hit_count(scores: &[f32], selected: &[i32], capacity: usize) -> u64 {
        if capacity == 0 || scores.is_empty() {
            return 0;
        }
        let mut ranked: Vec<(f32, usize)> = scores
            .iter()
            .copied()
            .enumerate()
            .filter_map(|(idx, score)| {
                if score > 0.0 && score.is_finite() {
                    Some((score, idx))
                } else {
                    None
                }
            })
            .collect();
        if ranked.is_empty() {
            return 0;
        }
        ranked.sort_by(|a, b| {
            b.0.partial_cmp(&a.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.1.cmp(&b.1))
        });
        ranked.truncate(capacity.min(ranked.len()));
        let mut hits = 0u64;
        for &eid in selected {
            if eid >= 0 {
                let eid = eid as usize;
                if ranked.iter().any(|&(_, idx)| idx == eid) {
                    hits += 1;
                }
            }
        }
        hits
    }

    fn split_caps(capacity: usize, split_pct: f64) -> (usize, usize) {
        let pin = ((capacity as f64) * split_pct / 100.0).round() as usize;
        let pin = pin.min(capacity);
        (pin, capacity.saturating_sub(pin))
    }

    fn heatmap_lru_hit_count(
        heatmap_rank: &[usize],
        lru_cache: &[i32],
        selected: &[i32],
        pin_capacity: usize,
    ) -> u64 {
        let mut hits = 0u64;
        for &eid in selected {
            if Self::heatmap_hit(heatmap_rank, eid, pin_capacity) || lru_cache.contains(&eid) {
                hits += 1;
            }
        }
        hits
    }

    fn record(
        &mut self,
        layer_idx: usize,
        num_experts: usize,
        topk: usize,
        topk_ids: &[i32],
        hcs: Option<&HcsState>,
    ) {
        if !self.enabled || num_experts == 0 || topk == 0 {
            return;
        }
        self.ensure_layer(layer_idx, num_experts);
        self.ensure_heatmap_rank(layer_idx, num_experts, hcs);

        let selected: Vec<i32> = topk_ids
            .iter()
            .take(topk)
            .copied()
            .filter(|&eid| eid >= 0 && (eid as usize) < num_experts)
            .collect();
        if selected.is_empty() {
            return;
        }

        self.route_events += 1;
        self.selected_total += selected.len() as u64;
        self.layer_stats[layer_idx].selected += selected.len() as u64;

        if let Some(hcs) = hcs {
            if hcs.num_cached > 0
                && !self
                    .global_lru_states
                    .iter()
                    .any(|state| state.capacity == hcs.num_cached)
            {
                self.global_lru_states
                    .push(RouteLocalityGlobalLruState::new(hcs.num_cached));
                self.global_lru_states.sort_by_key(|state| state.capacity);
            }
            self.actual_hcs_cached = hcs.num_cached;
            self.actual_hcs_possible = hcs
                .cache_fast_num_layers
                .saturating_mul(hcs.num_experts_per_layer);
            for &eid in selected.iter() {
                if eid >= 0 && hcs.get_fast(layer_idx, eid as usize).is_some() {
                    self.actual_hcs_hits += 1;
                    self.layer_stats[layer_idx].actual_hcs_hits += 1;
                }
            }
        }

        for state in self.global_lru_states.iter_mut() {
            state.record(layer_idx, &selected);
        }

        let prev = &self.previous_by_layer[layer_idx];
        for &eid in selected.iter() {
            if prev.contains(&eid) {
                self.last1_hits += 1;
                self.layer_stats[layer_idx].last1_hits += 1;
            }
        }

        let heatmap_rank = self.heatmap_rank_by_layer[layer_idx].clone();
        let policy_count = self.coverage_pcts.len();
        let mut heatmap_hits_by_policy = vec![0u64; policy_count];
        let mut lru_hits_by_policy = vec![0u64; policy_count];
        let mut heatmap_lru_hits_by_policy = vec![0u64; policy_count];
        let mut decayed_lfu_hits_by_policy = vec![0u64; policy_count];
        let mut adaptive_hits_by_policy = vec![0u64; policy_count];

        for policy_idx in 0..policy_count {
            let pct = self.coverage_pcts[policy_idx];
            let capacity = Self::coverage_capacity(num_experts, pct);
            let (pin_capacity, lru_tail_capacity) =
                Self::split_caps(capacity, self.heatmap_pin_pct);
            let state = &mut self.policy_states[policy_idx];

            let heatmap_hits = selected
                .iter()
                .filter(|&&eid| Self::heatmap_hit(&heatmap_rank, eid, capacity))
                .count() as u64;
            heatmap_hits_by_policy[policy_idx] = heatmap_hits;
            state.heatmap_hits += heatmap_hits;

            let lru_cache = &mut state.lru_by_layer[layer_idx];
            for &eid in selected.iter() {
                if lru_cache.contains(&eid) {
                    lru_hits_by_policy[policy_idx] += 1;
                }
            }
            state.lru_hits += lru_hits_by_policy[policy_idx];

            let heatmap_lru_cache = &mut state.heatmap_lru_by_layer[layer_idx];
            let heatmap_lru_hits = Self::heatmap_lru_hit_count(
                &heatmap_rank,
                heatmap_lru_cache,
                &selected,
                pin_capacity,
            );
            heatmap_lru_hits_by_policy[policy_idx] = heatmap_lru_hits;
            state.heatmap_lru_hits += heatmap_lru_hits;

            let lfu_hits =
                Self::lfu_hit_count(&state.lfu_scores_by_layer[layer_idx], &selected, capacity);
            decayed_lfu_hits_by_policy[policy_idx] = lfu_hits;
            state.decayed_lfu_hits += lfu_hits;

            let mut best_split_idx = 0usize;
            let mut best_score = f64::NEG_INFINITY;
            for split_idx in 0..ROUTE_LOCALITY_ADAPTIVE_SPLITS.len() {
                let score = state.adaptive_score_by_split_layer[split_idx][layer_idx];
                if score > best_score {
                    best_score = score;
                    best_split_idx = split_idx;
                }
            }

            let mut split_hits = vec![0u64; ROUTE_LOCALITY_ADAPTIVE_SPLITS.len()];
            for (split_idx, split_pct) in ROUTE_LOCALITY_ADAPTIVE_SPLITS.iter().copied().enumerate()
            {
                let (split_pin, _) = Self::split_caps(capacity, split_pct);
                let cache = &state.adaptive_lru_by_split_layer[split_idx][layer_idx];
                split_hits[split_idx] =
                    Self::heatmap_lru_hit_count(&heatmap_rank, cache, &selected, split_pin);
            }
            let adaptive_hits = split_hits[best_split_idx];
            adaptive_hits_by_policy[policy_idx] = adaptive_hits;
            state.adaptive_hits += adaptive_hits;

            for (split_idx, split_pct) in ROUTE_LOCALITY_ADAPTIVE_SPLITS.iter().copied().enumerate()
            {
                let (split_pin, split_tail) = Self::split_caps(capacity, split_pct);
                let hit_rate = split_hits[split_idx] as f64 / selected.len() as f64;
                let score = &mut state.adaptive_score_by_split_layer[split_idx][layer_idx];
                *score = *score * ROUTE_LOCALITY_ADAPTIVE_DECAY + hit_rate;
                let cache = &mut state.adaptive_lru_by_split_layer[split_idx][layer_idx];
                for &eid in selected.iter().rev() {
                    if !Self::heatmap_hit(&heatmap_rank, eid, split_pin) {
                        Self::update_lru(cache, eid, split_tail);
                    }
                }
            }

            for &eid in selected.iter().rev() {
                Self::update_lru(lru_cache, eid, capacity);
                if !Self::heatmap_hit(&heatmap_rank, eid, pin_capacity) {
                    Self::update_lru(heatmap_lru_cache, eid, lru_tail_capacity);
                }
            }
            for score in state.lfu_scores_by_layer[layer_idx].iter_mut() {
                *score *= ROUTE_LOCALITY_LFU_DECAY;
            }
            for &eid in selected.iter() {
                if eid >= 0 {
                    let idx = eid as usize;
                    if idx < state.lfu_scores_by_layer[layer_idx].len() {
                        state.lfu_scores_by_layer[layer_idx][idx] += 1.0;
                    }
                }
            }
        }

        for policy_idx in 0..policy_count {
            self.layer_stats[layer_idx].heatmap_hits[policy_idx] +=
                heatmap_hits_by_policy[policy_idx];
            self.layer_stats[layer_idx].lru_hits[policy_idx] += lru_hits_by_policy[policy_idx];
            self.layer_stats[layer_idx].heatmap_lru_hits[policy_idx] +=
                heatmap_lru_hits_by_policy[policy_idx];
            self.layer_stats[layer_idx].decayed_lfu_hits[policy_idx] +=
                decayed_lfu_hits_by_policy[policy_idx];
            self.layer_stats[layer_idx].adaptive_hits[policy_idx] +=
                adaptive_hits_by_policy[policy_idx];
        }
        self.previous_by_layer[layer_idx] = selected;
    }

    fn emit_summary(&self, generated_tokens: usize) {
        if !self.enabled || self.selected_total == 0 {
            return;
        }
        let selected = self.selected_total as f64;
        let last1_rate = self.last1_hits as f64 / selected;
        let routes_per_token = if generated_tokens > 0 {
            self.route_events as f64 / generated_tokens as f64
        } else {
            0.0
        };
        let selected_per_token = if generated_tokens > 0 {
            self.selected_total as f64 / generated_tokens as f64
        } else {
            0.0
        };

        let format_policy = |label: &str, values: Vec<u64>| -> String {
            let parts: Vec<String> = self
                .coverage_pcts
                .iter()
                .zip(values.iter())
                .map(|(pct, hits)| {
                    let rate = *hits as f64 / selected;
                    let lift = rate / (*pct / 100.0);
                    format!("{:.1}%:{:.2}%/{:.2}x", pct, rate * 100.0, lift)
                })
                .collect();
            format!("{}=[{}]", label, parts.join(", "))
        };

        let heatmap_parts = format_policy(
            "heatmap",
            self.policy_states.iter().map(|s| s.heatmap_hits).collect(),
        );
        let lru_parts = format_policy(
            "lru",
            self.policy_states.iter().map(|s| s.lru_hits).collect(),
        );
        let heatmap_lru_parts = format_policy(
            "heatmap_lru",
            self.policy_states
                .iter()
                .map(|s| s.heatmap_lru_hits)
                .collect(),
        );
        let lfu_parts = format_policy(
            "decayed_lfu",
            self.policy_states
                .iter()
                .map(|s| s.decayed_lfu_hits)
                .collect(),
        );
        let adaptive_parts = format_policy(
            "adaptive",
            self.policy_states.iter().map(|s| s.adaptive_hits).collect(),
        );
        let global_lru_parts = self
            .global_lru_states
            .iter()
            .map(|state| {
                format!(
                    "{}:{:.2}%",
                    state.capacity,
                    state.hits as f64 / selected * 100.0
                )
            })
            .collect::<Vec<_>>()
            .join(", ");

        let actual_hcs_rate = self.actual_hcs_hits as f64 / selected;
        let actual_hcs_coverage = if self.actual_hcs_possible > 0 {
            self.actual_hcs_cached as f64 / self.actual_hcs_possible as f64
        } else {
            0.0
        };
        let actual_hcs_lift = if actual_hcs_coverage > 0.0 {
            actual_hcs_rate / actual_hcs_coverage
        } else {
            0.0
        };
        let heatmap_ranked_layers = self
            .heatmap_rank_by_layer
            .iter()
            .filter(|ranks| ranks.iter().any(|&rank| rank != usize::MAX))
            .count();

        let lru_policy_parts: Vec<String> = self
            .coverage_pcts
            .iter()
            .enumerate()
            .map(|(idx, pct)| {
                let rate = self.policy_states[idx].lru_hits as f64 / selected;
                let lift = rate / (*pct / 100.0);
                format!("{:.1}%:{:.2}%/{:.2}x", pct, rate * 100.0, lift)
            })
            .collect();

        let focus_idx = self
            .coverage_pcts
            .iter()
            .enumerate()
            .min_by(|(_, a), (_, b)| {
                ((*a - 15.0).abs())
                    .partial_cmp(&((*b - 15.0).abs()))
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|(idx, _)| idx);
        let top_layers = if let Some(policy_idx) = focus_idx {
            let mut layers: Vec<(usize, u64, u64, u64)> = self
                .layer_stats
                .iter()
                .enumerate()
                .filter_map(|(layer, st)| {
                    if st.selected == 0 {
                        None
                    } else {
                        Some((
                            layer,
                            st.selected,
                            st.last1_hits,
                            *st.lru_hits.get(policy_idx).unwrap_or(&0),
                        ))
                    }
                })
                .collect();
            layers.sort_by(|a, b| {
                let ar = a.3 as f64 / a.1.max(1) as f64;
                let br = b.3 as f64 / b.1.max(1) as f64;
                br.partial_cmp(&ar).unwrap_or(std::cmp::Ordering::Equal)
            });
            layers
                .iter()
                .take(8)
                .map(|(layer, selected, last1, lru)| {
                    format!(
                        "L{}:last1={:.1}% lru={:.1}%",
                        layer,
                        *last1 as f64 / *selected as f64 * 100.0,
                        *lru as f64 / *selected as f64 * 100.0,
                    )
                })
                .collect::<Vec<_>>()
                .join("; ")
        } else {
            String::new()
        };

        eprintln!("  \x1b[36m┌─────────────────────────────────────────────────┐\x1b[0m");
        eprintln!("  \x1b[36m│\x1b[0m  ROUTE LOCALITY DIAGNOSTIC                 \x1b[36m│\x1b[0m");
        eprintln!("  \x1b[36m├─────────────────────────────────────────────────┤\x1b[0m");
        eprintln!(
            "  \x1b[36m│\x1b[0m  Routes: {} | selected: {} | selected/tok: {:.1} \x1b[36m│\x1b[0m",
            self.route_events, self.selected_total, selected_per_token
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Prev-token same-layer overlap: {:.2}%        \x1b[36m│\x1b[0m",
            last1_rate * 100.0
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Actual HCS: {:.2}% hit, {:.2}x lift       \x1b[36m│\x1b[0m",
            actual_hcs_rate * 100.0,
            actual_hcs_lift
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Heatmap-only: {} \x1b[36m│\x1b[0m",
            heatmap_parts.trim_start_matches("heatmap=")
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  LRU: {} \x1b[36m│\x1b[0m",
            lru_parts.trim_start_matches("lru=")
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Heatmap+LRU: {} \x1b[36m│\x1b[0m",
            heatmap_lru_parts.trim_start_matches("heatmap_lru=")
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Decayed LFU: {} \x1b[36m│\x1b[0m",
            lfu_parts.trim_start_matches("decayed_lfu=")
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Adaptive: {} \x1b[36m│\x1b[0m",
            adaptive_parts.trim_start_matches("adaptive=")
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Global LRU cold-start: [{}] \x1b[36m│\x1b[0m",
            global_lru_parts
        );
        eprintln!("  \x1b[36m└─────────────────────────────────────────────────┘\x1b[0m");

        log::info!(
            "ROUTE LOCALITY SUMMARY generated={} routes={} routes_per_token={:.3} selected={} selected_per_token={:.3} last1_hits={} last1_hit_rate_pct={:.4} actual_hcs_hits={} actual_hcs_hit_rate_pct={:.4} actual_hcs_cached={} actual_hcs_possible={} actual_hcs_coverage_pct={:.4} actual_hcs_lift={:.4} heatmap_ranked_layers={} {} {} {} {} {} global_lru_cold=[{}] lru_legacy=[{}] top_layers=[{}]",
            generated_tokens,
            self.route_events,
            routes_per_token,
            self.selected_total,
            selected_per_token,
            self.last1_hits,
            last1_rate * 100.0,
            self.actual_hcs_hits,
            actual_hcs_rate * 100.0,
            self.actual_hcs_cached,
            self.actual_hcs_possible,
            actual_hcs_coverage * 100.0,
            actual_hcs_lift,
            heatmap_ranked_layers,
            heatmap_parts,
            lru_parts,
            heatmap_lru_parts,
            lfu_parts,
            adaptive_parts,
            global_lru_parts,
            lru_policy_parts.join(", "),
            top_layers,
        );
    }
}

#[derive(Clone, Default)]
struct RouteSwapShadowLayerStats {
    low_cold: u64,
    matched: u64,
    matched_weight_sum: f64,
}

#[derive(Clone)]
struct RouteSwapShadowStats {
    enabled: bool,
    protect_rank_pct: f64,
    abs_tol: f32,
    rel_tol: f32,
    route_events: u64,
    selected_total: u64,
    cold_selected: u64,
    hcs_selected: u64,
    protected_selected: u64,
    protected_cold: u64,
    low_rank_selected: u64,
    low_rank_cold: u64,
    matched_cold: u64,
    unmatched_no_resident: u64,
    unmatched_not_similar: u64,
    selected_weight_sum: f64,
    cold_weight_sum: f64,
    low_cold_weight_sum: f64,
    matched_weight_sum: f64,
    matched_delta_sum: f64,
    matched_rel_delta_sum: f64,
    matched_delta_max: f32,
    matched_rel_delta_max: f32,
    layer_stats: Vec<RouteSwapShadowLayerStats>,
}

impl RouteSwapShadowStats {
    fn from_env() -> Self {
        let enabled = env_truthy("KRASIS_ROUTE_SWAP_SHADOW");
        let protect_rank_pct =
            env_f64("KRASIS_ROUTE_SWAP_PROTECT_RANK_PCT", 75.0).clamp(0.0, 100.0);
        let abs_tol = env_f64("KRASIS_ROUTE_SWAP_ABS_TOL", 0.005).max(0.0) as f32;
        let rel_tol = (env_f64("KRASIS_ROUTE_SWAP_REL_TOL_PCT", 10.0).max(0.0) / 100.0) as f32;
        let s = Self {
            enabled,
            protect_rank_pct,
            abs_tol,
            rel_tol,
            route_events: 0,
            selected_total: 0,
            cold_selected: 0,
            hcs_selected: 0,
            protected_selected: 0,
            protected_cold: 0,
            low_rank_selected: 0,
            low_rank_cold: 0,
            matched_cold: 0,
            unmatched_no_resident: 0,
            unmatched_not_similar: 0,
            selected_weight_sum: 0.0,
            cold_weight_sum: 0.0,
            low_cold_weight_sum: 0.0,
            matched_weight_sum: 0.0,
            matched_delta_sum: 0.0,
            matched_rel_delta_sum: 0.0,
            matched_delta_max: 0.0,
            matched_rel_delta_max: 0.0,
            layer_stats: Vec::new(),
        };
        if enabled {
            log::info!(
                "ROUTE SWAP SHADOW enabled: protect_rank_pct={:.1} abs_tol={:.6} rel_tol_pct={:.2}",
                s.protect_rank_pct,
                s.abs_tol,
                s.rel_tol * 100.0,
            );
        }
        s
    }

    fn reset_counts(&mut self) {
        self.route_events = 0;
        self.selected_total = 0;
        self.cold_selected = 0;
        self.hcs_selected = 0;
        self.protected_selected = 0;
        self.protected_cold = 0;
        self.low_rank_selected = 0;
        self.low_rank_cold = 0;
        self.matched_cold = 0;
        self.unmatched_no_resident = 0;
        self.unmatched_not_similar = 0;
        self.selected_weight_sum = 0.0;
        self.cold_weight_sum = 0.0;
        self.low_cold_weight_sum = 0.0;
        self.matched_weight_sum = 0.0;
        self.matched_delta_sum = 0.0;
        self.matched_rel_delta_sum = 0.0;
        self.matched_delta_max = 0.0;
        self.matched_rel_delta_max = 0.0;
        self.layer_stats.clear();
    }

    fn record(
        &mut self,
        layer_idx: usize,
        num_experts: usize,
        topk: usize,
        topk_ids: &[i32],
        topk_weights: &[f32],
        scores: &[f32],
        hcs: Option<&HcsState>,
    ) {
        if !self.enabled || topk == 0 || num_experts == 0 || scores.len() < num_experts {
            return;
        }
        let Some(hcs) = hcs else {
            return;
        };
        if self.layer_stats.len() <= layer_idx {
            self.layer_stats
                .resize_with(layer_idx + 1, RouteSwapShadowLayerStats::default);
        }

        self.route_events += 1;
        let protected_count = ((topk as f64) * self.protect_rank_pct / 100.0)
            .ceil()
            .max(0.0) as usize;
        let protected_count = protected_count.min(topk);

        let mut selected = vec![false; num_experts];
        let mut used_replacement = vec![false; num_experts];
        for &raw in topk_ids.iter().take(topk) {
            if raw >= 0 {
                let eid = raw as usize;
                if eid < num_experts {
                    selected[eid] = true;
                    used_replacement[eid] = true;
                }
            }
        }

        for i in 0..topk {
            let raw_eid = *topk_ids.get(i).unwrap_or(&-1);
            if raw_eid < 0 {
                continue;
            }
            let eid = raw_eid as usize;
            if eid >= num_experts {
                continue;
            }
            let weight = *topk_weights.get(i).unwrap_or(&0.0);
            self.selected_total += 1;
            self.selected_weight_sum += weight as f64;

            let resident = hcs.get_fast(layer_idx, eid).is_some();
            if resident {
                self.hcs_selected += 1;
            } else {
                self.cold_selected += 1;
                self.cold_weight_sum += weight as f64;
            }

            if i < protected_count {
                self.protected_selected += 1;
                if !resident {
                    self.protected_cold += 1;
                }
                continue;
            }

            self.low_rank_selected += 1;
            if resident {
                continue;
            }

            self.low_rank_cold += 1;
            self.low_cold_weight_sum += weight as f64;
            self.layer_stats[layer_idx].low_cold += 1;

            let target_score = scores[eid];
            if !target_score.is_finite() {
                self.unmatched_not_similar += 1;
                continue;
            }
            let threshold = self.abs_tol.max(target_score.abs() * self.rel_tol);
            let mut best: Option<(usize, f32, f32)> = None;
            let mut resident_candidates = 0usize;
            for cand in 0..num_experts {
                if selected[cand] || used_replacement[cand] {
                    continue;
                }
                if hcs.get_fast(layer_idx, cand).is_none() {
                    continue;
                }
                resident_candidates += 1;
                let cand_score = scores[cand];
                if !cand_score.is_finite() {
                    continue;
                }
                let delta = (cand_score - target_score).abs();
                if delta <= threshold {
                    let rel = delta / target_score.abs().max(1.0e-9);
                    match best {
                        Some((_, best_delta, _)) if delta >= best_delta => {}
                        _ => best = Some((cand, delta, rel)),
                    }
                }
            }

            if let Some((cand, delta, rel)) = best {
                used_replacement[cand] = true;
                self.matched_cold += 1;
                self.matched_weight_sum += weight as f64;
                self.matched_delta_sum += delta as f64;
                self.matched_rel_delta_sum += rel as f64;
                self.matched_delta_max = self.matched_delta_max.max(delta);
                self.matched_rel_delta_max = self.matched_rel_delta_max.max(rel);
                self.layer_stats[layer_idx].matched += 1;
                self.layer_stats[layer_idx].matched_weight_sum += weight as f64;
            } else if resident_candidates == 0 {
                self.unmatched_no_resident += 1;
            } else {
                self.unmatched_not_similar += 1;
            }
        }
    }

    fn emit_summary(&self, generated_tokens: usize, exact_cold_experts: u64) {
        if !self.enabled || self.route_events == 0 {
            return;
        }
        let tokens = generated_tokens.max(1) as f64;
        let low_cold = self.low_rank_cold.max(1) as f64;
        let matched = self.matched_cold as f64;
        let matched_pct_low_cold = matched / low_cold * 100.0;
        let exact_cold_per_tok = exact_cold_experts as f64 / tokens;
        let avoided_per_tok = self.matched_cold as f64 / tokens;
        let avoided_pct_exact_cold = if exact_cold_experts > 0 {
            self.matched_cold as f64 / exact_cold_experts as f64 * 100.0
        } else {
            0.0
        };
        let avg_delta = if self.matched_cold > 0 {
            self.matched_delta_sum / self.matched_cold as f64
        } else {
            0.0
        };
        let avg_rel_delta = if self.matched_cold > 0 {
            self.matched_rel_delta_sum / self.matched_cold as f64 * 100.0
        } else {
            0.0
        };
        let mut layer_top: Vec<(usize, u64, u64, f64)> = self
            .layer_stats
            .iter()
            .enumerate()
            .filter_map(|(idx, st)| {
                if st.low_cold == 0 && st.matched == 0 {
                    None
                } else {
                    Some((idx, st.low_cold, st.matched, st.matched_weight_sum))
                }
            })
            .collect();
        layer_top.sort_by(|a, b| b.2.cmp(&a.2).then_with(|| b.1.cmp(&a.1)));
        let top_layers: Vec<String> = layer_top
            .iter()
            .take(8)
            .map(|(layer, low, matched, weight)| {
                format!("L{}:{}/{} w={:.4}", layer, matched, low, weight)
            })
            .collect();

        eprintln!("  \x1b[35m┌─────────────────────────────────────────────────┐\x1b[0m");
        eprintln!(
            "  \x1b[35m│\x1b[0m  ROUTE SWAP SHADOW (exact execution)          \x1b[35m│\x1b[0m"
        );
        eprintln!("  \x1b[35m├─────────────────────────────────────────────────┤\x1b[0m");
        eprintln!("  \x1b[35m│\x1b[0m  Policy: protect top {:4.1}% ranks, tol=max({:.4},{:.1}%) \x1b[35m│\x1b[0m",
            self.protect_rank_pct, self.abs_tol, self.rel_tol * 100.0);
        eprintln!(
            "  \x1b[35m│\x1b[0m  Routes: {} | selected: {} | cold: {}        \x1b[35m│\x1b[0m",
            self.route_events, self.selected_total, self.cold_selected
        );
        eprintln!(
            "  \x1b[35m│\x1b[0m  Low-rank cold: {} | matched: {} ({:.1}%)       \x1b[35m│\x1b[0m",
            self.low_rank_cold, self.matched_cold, matched_pct_low_cold
        );
        eprintln!("  \x1b[35m│\x1b[0m  Estimated cold saved: {:.1}/tok ({:.1}% of exact cold) \x1b[35m│\x1b[0m",
            avoided_per_tok, avoided_pct_exact_cold);
        eprintln!(
            "  \x1b[35m│\x1b[0m  Affected weight mass: {:.4} total, {:.6}/tok   \x1b[35m│\x1b[0m",
            self.matched_weight_sum,
            self.matched_weight_sum / tokens
        );
        eprintln!("  \x1b[35m│\x1b[0m  Score delta: avg {:.6}, max {:.6}, rel avg {:.2}% max {:.2}% \x1b[35m│\x1b[0m",
            avg_delta, self.matched_delta_max, avg_rel_delta, self.matched_rel_delta_max * 100.0);
        eprintln!("  \x1b[35m└─────────────────────────────────────────────────┘\x1b[0m");

        log::info!(
            "ROUTE SWAP SHADOW SUMMARY generated={} routes={} selected={} cold={} hcs={} protected_cold={} low_cold={} matched={} unmatched_no_resident={} unmatched_not_similar={} exact_cold_per_tok={:.3} estimated_saved_per_tok={:.3} estimated_saved_pct_exact_cold={:.2} affected_weight_sum={:.6} affected_weight_per_tok={:.8} avg_score_delta={:.8} max_score_delta={:.8} avg_rel_delta_pct={:.4} max_rel_delta_pct={:.4} protect_rank_pct={:.2} abs_tol={:.6} rel_tol_pct={:.4} top_layers=[{}]",
            generated_tokens,
            self.route_events,
            self.selected_total,
            self.cold_selected,
            self.hcs_selected,
            self.protected_cold,
            self.low_rank_cold,
            self.matched_cold,
            self.unmatched_no_resident,
            self.unmatched_not_similar,
            exact_cold_per_tok,
            avoided_per_tok,
            avoided_pct_exact_cold,
            self.matched_weight_sum,
            self.matched_weight_sum / tokens,
            avg_delta,
            self.matched_delta_max,
            avg_rel_delta,
            self.matched_rel_delta_max * 100.0,
            self.protect_rank_pct,
            self.abs_tol,
            self.rel_tol * 100.0,
            top_layers.join("; "),
        );
    }
}

#[derive(Clone, Debug)]
struct HcsColdSwapApplied {
    topk_pos: usize,
    original_expert: usize,
    replacement_expert: usize,
    weight: f32,
    delta: f32,
    rel_delta: f32,
}

#[derive(Clone)]
struct HcsColdSwapStats {
    enabled: bool,
    log_enabled: bool,
    protect_rank_pct: f64,
    abs_tol: f32,
    rel_tol: f32,
    route_events: u64,
    selected_total: u64,
    cold_selected: u64,
    protected_cold: u64,
    low_rank_cold: u64,
    swapped: u64,
    unmatched_no_resident: u64,
    unmatched_not_similar: u64,
    affected_weight_sum: f64,
    delta_sum: f64,
    rel_delta_sum: f64,
    delta_max: f32,
    rel_delta_max: f32,
}

impl HcsColdSwapStats {
    fn from_env() -> Self {
        let enabled = env_truthy("KRASIS_HCS_COLD_SWAP");
        let protect_rank_pct =
            env_f64("KRASIS_ROUTE_SWAP_PROTECT_RANK_PCT", 75.0).clamp(0.0, 100.0);
        let abs_tol = env_f64("KRASIS_ROUTE_SWAP_ABS_TOL", 0.005).max(0.0) as f32;
        let rel_tol = (env_f64("KRASIS_ROUTE_SWAP_REL_TOL_PCT", 10.0).max(0.0) / 100.0) as f32;
        let s = Self {
            enabled,
            log_enabled: env_truthy("KRASIS_HCS_COLD_SWAP_LOG"),
            protect_rank_pct,
            abs_tol,
            rel_tol,
            route_events: 0,
            selected_total: 0,
            cold_selected: 0,
            protected_cold: 0,
            low_rank_cold: 0,
            swapped: 0,
            unmatched_no_resident: 0,
            unmatched_not_similar: 0,
            affected_weight_sum: 0.0,
            delta_sum: 0.0,
            rel_delta_sum: 0.0,
            delta_max: 0.0,
            rel_delta_max: 0.0,
        };
        if enabled {
            log::warn!(
                "HCS cold swaps enabled: approximate decode mode protect_rank_pct={:.1} abs_tol={:.6} rel_tol_pct={:.2}",
                s.protect_rank_pct,
                s.abs_tol,
                s.rel_tol * 100.0,
            );
        }
        s
    }

    fn reset_counts(&mut self) {
        self.route_events = 0;
        self.selected_total = 0;
        self.cold_selected = 0;
        self.protected_cold = 0;
        self.low_rank_cold = 0;
        self.swapped = 0;
        self.unmatched_no_resident = 0;
        self.unmatched_not_similar = 0;
        self.affected_weight_sum = 0.0;
        self.delta_sum = 0.0;
        self.rel_delta_sum = 0.0;
        self.delta_max = 0.0;
        self.rel_delta_max = 0.0;
    }

    fn plan(
        &self,
        layer_idx: usize,
        num_experts: usize,
        topk: usize,
        topk_ids: &[i32],
        topk_weights: &[f32],
        scores: &[f32],
        hcs: &HcsState,
    ) -> Result<Vec<HcsColdSwapApplied>, String> {
        if !self.enabled {
            return Ok(Vec::new());
        }
        if topk == 0 || num_experts == 0 {
            return Ok(Vec::new());
        }
        if scores.len() < num_experts {
            return Err(format!(
                "HCS cold swap enabled but router scores are incomplete layer={} scores={} experts={}",
                layer_idx,
                scores.len(),
                num_experts,
            ));
        }

        let protected_count = ((topk as f64) * self.protect_rank_pct / 100.0)
            .ceil()
            .max(0.0) as usize;
        let protected_count = protected_count.min(topk);

        let mut selected = vec![false; num_experts];
        let mut used_replacement = vec![false; num_experts];
        for &raw in topk_ids.iter().take(topk) {
            if raw >= 0 {
                let eid = raw as usize;
                if eid < num_experts {
                    selected[eid] = true;
                    used_replacement[eid] = true;
                }
            }
        }

        let mut swaps = Vec::new();
        for i in protected_count..topk {
            let raw_eid = *topk_ids.get(i).unwrap_or(&-1);
            if raw_eid < 0 {
                continue;
            }
            let eid = raw_eid as usize;
            if eid >= num_experts || hcs.get_fast(layer_idx, eid).is_some() {
                continue;
            }

            let target_score = scores[eid];
            if !target_score.is_finite() {
                continue;
            }
            let threshold = self.abs_tol.max(target_score.abs() * self.rel_tol);
            let mut best: Option<(usize, f32, f32)> = None;
            for cand in 0..num_experts {
                if selected[cand] || used_replacement[cand] {
                    continue;
                }
                if hcs.get_fast(layer_idx, cand).is_none() {
                    continue;
                }
                let cand_score = scores[cand];
                if !cand_score.is_finite() {
                    continue;
                }
                let delta = (cand_score - target_score).abs();
                if delta <= threshold {
                    let rel = delta / target_score.abs().max(1.0e-9);
                    match best {
                        Some((_, best_delta, _)) if delta >= best_delta => {}
                        _ => best = Some((cand, delta, rel)),
                    }
                }
            }

            if let Some((replacement, delta, rel_delta)) = best {
                used_replacement[replacement] = true;
                swaps.push(HcsColdSwapApplied {
                    topk_pos: i,
                    original_expert: eid,
                    replacement_expert: replacement,
                    weight: *topk_weights.get(i).unwrap_or(&0.0),
                    delta,
                    rel_delta,
                });
            }
        }
        Ok(swaps)
    }

    fn record_route(
        &mut self,
        layer_idx: usize,
        num_experts: usize,
        topk: usize,
        original_topk_ids: &[i32],
        hcs: Option<&HcsState>,
        swaps: &[HcsColdSwapApplied],
    ) {
        if !self.enabled {
            return;
        }
        self.route_events += 1;
        let protected_count = ((topk as f64) * self.protect_rank_pct / 100.0)
            .ceil()
            .max(0.0) as usize;
        let protected_count = protected_count.min(topk);

        if let Some(hcs) = hcs {
            for (i, &raw) in original_topk_ids.iter().take(topk).enumerate() {
                if raw < 0 {
                    continue;
                }
                let eid = raw as usize;
                if eid >= num_experts {
                    continue;
                }
                self.selected_total += 1;
                if hcs.get_fast(layer_idx, eid).is_some() {
                    continue;
                }
                self.cold_selected += 1;
                if i < protected_count {
                    self.protected_cold += 1;
                } else {
                    self.low_rank_cold += 1;
                }
            }
        }

        for swap in swaps {
            self.swapped += 1;
            self.affected_weight_sum += swap.weight as f64;
            self.delta_sum += swap.delta as f64;
            self.rel_delta_sum += swap.rel_delta as f64;
            self.delta_max = self.delta_max.max(swap.delta);
            self.rel_delta_max = self.rel_delta_max.max(swap.rel_delta);
            if self.log_enabled {
                log::info!(
                    "HCS COLD SWAP layer={} rank={} original={} replacement={} weight={:.6} delta={:.8} rel_delta_pct={:.4}",
                    layer_idx,
                    swap.topk_pos,
                    swap.original_expert,
                    swap.replacement_expert,
                    swap.weight,
                    swap.delta,
                    swap.rel_delta * 100.0,
                );
            }
        }
        let unmatched_low = self.low_rank_cold.saturating_sub(self.swapped);
        self.unmatched_not_similar = unmatched_low;
    }

    fn emit_summary(&self, generated_tokens: usize, actual_cold_experts: u64) {
        if !self.enabled || self.route_events == 0 {
            return;
        }
        let tokens = generated_tokens.max(1) as f64;
        let swapped = self.swapped as f64;
        let avg_delta = if self.swapped > 0 {
            self.delta_sum / self.swapped as f64
        } else {
            0.0
        };
        let avg_rel_delta = if self.swapped > 0 {
            self.rel_delta_sum / self.swapped as f64 * 100.0
        } else {
            0.0
        };
        let cold_per_tok = actual_cold_experts as f64 / tokens;
        let swapped_per_tok = swapped / tokens;
        let swapped_pct = if self.cold_selected > 0 {
            self.swapped as f64 / self.cold_selected as f64 * 100.0
        } else {
            0.0
        };
        eprintln!("  \x1b[33m┌─────────────────────────────────────────────────┐\x1b[0m");
        eprintln!(
            "  \x1b[33m│\x1b[0m  HCS COLD SWAPS (approximate decode)        \x1b[33m│\x1b[0m"
        );
        eprintln!("  \x1b[33m├─────────────────────────────────────────────────┤\x1b[0m");
        eprintln!("  \x1b[33m│\x1b[0m  Policy: protect top {:4.1}% ranks, tol=max({:.4},{:.1}%) \x1b[33m│\x1b[0m",
            self.protect_rank_pct, self.abs_tol, self.rel_tol * 100.0);
        eprintln!(
            "  \x1b[33m│\x1b[0m  Swapped: {} ({:.2}/tok, {:.1}% of original cold) \x1b[33m│\x1b[0m",
            self.swapped, swapped_per_tok, swapped_pct
        );
        eprintln!(
            "  \x1b[33m│\x1b[0m  Actual cold after swaps: {:.2}/tok              \x1b[33m│\x1b[0m",
            cold_per_tok
        );
        eprintln!("  \x1b[33m│\x1b[0m  Score delta: avg {:.6}, max {:.6}, rel avg {:.2}% max {:.2}% \x1b[33m│\x1b[0m",
            avg_delta, self.delta_max, avg_rel_delta, self.rel_delta_max * 100.0);
        eprintln!("  \x1b[33m└─────────────────────────────────────────────────┘\x1b[0m");
        log::info!(
            "HCS COLD SWAP SUMMARY generated={} routes={} selected={} original_cold={} protected_cold={} low_cold={} swapped={} swapped_per_tok={:.4} swapped_pct_original_cold={:.2} actual_cold_after_swap={} actual_cold_per_tok={:.4} affected_weight_sum={:.6} affected_weight_per_tok={:.8} avg_score_delta={:.8} max_score_delta={:.8} avg_rel_delta_pct={:.4} max_rel_delta_pct={:.4} protect_rank_pct={:.2} abs_tol={:.6} rel_tol_pct={:.4}",
            generated_tokens,
            self.route_events,
            self.selected_total,
            self.cold_selected,
            self.protected_cold,
            self.low_rank_cold,
            self.swapped,
            swapped_per_tok,
            swapped_pct,
            actual_cold_experts,
            cold_per_tok,
            self.affected_weight_sum,
            self.affected_weight_sum / tokens,
            avg_delta,
            self.delta_max,
            avg_rel_delta,
            self.rel_delta_max * 100.0,
            self.protect_rank_pct,
            self.abs_tol,
            self.rel_tol * 100.0,
        );
    }
}

#[derive(Clone, Default)]
struct PromptHcsShadowLayerStats {
    selected: u64,
    shadow_hcs: u64,
    extra_hits: u64,
    lost_hits: u64,
}

#[derive(Clone)]
struct PromptHcsShadowVariant {
    retain_pct: usize,
    heatmap_retained: usize,
    prompt_ranked: usize,
    backfilled: usize,
    candidate_resident: Vec<bool>,
    shadow_hcs: u64,
    shadow_cold: u64,
    extra_hits: u64,
    lost_hits: u64,
    layer_stats: Vec<PromptHcsShadowLayerStats>,
}

struct PromptHcsBlendPlan {
    retain_pct: usize,
    heatmap_retained: usize,
    prompt_ranked: usize,
    backfilled: usize,
    soft_capacity: usize,
    hard_resident: usize,
    prompt_ranked_candidates: usize,
    heatmap_candidates: usize,
    ranking: Vec<(usize, usize)>,
    candidate_resident: Vec<bool>,
}

#[derive(Clone)]
struct PromptHcsShadowStats {
    enabled: bool,
    prompt_tokens: usize,
    num_layers: usize,
    num_experts_per_layer: usize,
    soft_capacity: usize,
    hard_resident: usize,
    selected_total: u64,
    actual_hcs: u64,
    actual_cold: u64,
    variants: Vec<PromptHcsShadowVariant>,
}

impl PromptHcsShadowStats {
    const RETAIN_PCTS: [usize; 11] = [10, 20, 30, 40, 50, 60, 70, 75, 80, 85, 90];

    fn build_blend_plan(
        counts: &[u64],
        count_layers: usize,
        count_experts_per_layer: usize,
        hcs: &HcsState,
        retain_pct: usize,
        min_heatmap_slots: usize,
    ) -> Option<PromptHcsBlendPlan> {
        let num_layers = hcs.cache_fast_num_layers;
        let num_experts = hcs.num_experts_per_layer;
        let total = num_layers.saturating_mul(num_experts);
        if total == 0 || count_layers == 0 || count_experts_per_layer == 0 {
            return None;
        }

        let mut hard = vec![false; total];
        let mut candidate = vec![false; total];
        for idx in 0..total.min(hcs.cache_fast.len()) {
            if hcs.cache_fast[idx][0] != 0 {
                hard[idx] = true;
                candidate[idx] = true;
            }
        }

        for slot in 0..hcs.soft_slot_to_expert.len().min(hcs.soft_num_slots) {
            if let Some((layer_idx, expert_idx)) = hcs.soft_slot_to_expert[slot] {
                if layer_idx < num_layers && expert_idx < num_experts {
                    let idx = layer_idx * num_experts + expert_idx;
                    hard[idx] = false;
                    candidate[idx] = false;
                }
            }
        }
        let hard_resident = hard.iter().filter(|&&v| v).count();
        let soft_capacity = hcs.soft_num_slots;
        if soft_capacity == 0 {
            return None;
        }

        let mut prompt_ranked_candidates: Vec<(u64, usize, usize)> = Vec::new();
        for layer_idx in 0..num_layers.min(count_layers) {
            for expert_idx in 0..num_experts.min(count_experts_per_layer) {
                let hcs_idx = layer_idx * num_experts + expert_idx;
                if hard[hcs_idx] {
                    continue;
                }
                let count_idx = layer_idx * count_experts_per_layer + expert_idx;
                let count = counts.get(count_idx).copied().unwrap_or(0);
                if count > 0 {
                    prompt_ranked_candidates.push((count, layer_idx, expert_idx));
                }
            }
        }
        prompt_ranked_candidates.sort_by(|a, b| {
            b.0.cmp(&a.0)
                .then_with(|| a.1.cmp(&b.1))
                .then_with(|| a.2.cmp(&b.2))
        });
        let prompt_ranked_candidates_len = prompt_ranked_candidates.len();

        let heatmap_source = if hcs.soft_heatmap_ranking.is_empty() {
            &hcs.soft_ranking
        } else {
            &hcs.soft_heatmap_ranking
        };
        let mut heatmap_candidates: Vec<(usize, usize)> = Vec::new();
        for &(layer_idx, expert_idx) in heatmap_source {
            if layer_idx >= num_layers || expert_idx >= num_experts {
                continue;
            }
            let idx = layer_idx * num_experts + expert_idx;
            if hard[idx] {
                continue;
            }
            heatmap_candidates.push((layer_idx, expert_idx));
        }
        let heatmap_candidates_len = heatmap_candidates.len();

        let retain_slots = ((soft_capacity.saturating_mul(retain_pct) + 99) / 100)
            .max(min_heatmap_slots)
            .min(soft_capacity);
        let mut ranking: Vec<(usize, usize)> = Vec::with_capacity(soft_capacity);
        let mut heatmap_retained = 0usize;
        for &(layer_idx, expert_idx) in &heatmap_candidates {
            if heatmap_retained >= retain_slots || ranking.len() >= soft_capacity {
                break;
            }
            let idx = layer_idx * num_experts + expert_idx;
            if hard[idx] || candidate[idx] {
                continue;
            }
            candidate[idx] = true;
            ranking.push((layer_idx, expert_idx));
            heatmap_retained += 1;
        }

        let mut prompt_ranked = 0usize;
        for &(_, layer_idx, expert_idx) in &prompt_ranked_candidates {
            if ranking.len() >= soft_capacity {
                break;
            }
            let idx = layer_idx * num_experts + expert_idx;
            if hard[idx] || candidate[idx] {
                continue;
            }
            candidate[idx] = true;
            ranking.push((layer_idx, expert_idx));
            prompt_ranked += 1;
        }

        let mut backfilled = 0usize;
        if ranking.len() < soft_capacity {
            for &(layer_idx, expert_idx) in &heatmap_candidates {
                if ranking.len() >= soft_capacity {
                    break;
                }
                let idx = layer_idx * num_experts + expert_idx;
                if hard[idx] || candidate[idx] {
                    continue;
                }
                candidate[idx] = true;
                ranking.push((layer_idx, expert_idx));
                backfilled += 1;
            }
        }

        Some(PromptHcsBlendPlan {
            retain_pct,
            heatmap_retained,
            prompt_ranked,
            backfilled,
            soft_capacity,
            hard_resident,
            prompt_ranked_candidates: prompt_ranked_candidates_len,
            heatmap_candidates: heatmap_candidates_len,
            ranking,
            candidate_resident: candidate,
        })
    }

    fn disabled() -> Self {
        Self {
            enabled: false,
            prompt_tokens: 0,
            num_layers: 0,
            num_experts_per_layer: 0,
            soft_capacity: 0,
            hard_resident: 0,
            selected_total: 0,
            actual_hcs: 0,
            actual_cold: 0,
            variants: Vec::new(),
        }
    }

    fn build_from_prompt_counts(
        counts: &[u64],
        count_layers: usize,
        count_experts_per_layer: usize,
        prompt_tokens: usize,
        hcs: &HcsState,
    ) -> Self {
        if !env_truthy("KRASIS_PROMPT_HCS_SHADOW") {
            return Self::disabled();
        }
        let num_layers = hcs.cache_fast_num_layers;
        let num_experts = hcs.num_experts_per_layer;
        if num_layers == 0 || num_experts == 0 || count_layers == 0 || count_experts_per_layer == 0
        {
            log::warn!(
                "PROMPT HCS SHADOW disabled: invalid dimensions hcs_layers={} hcs_experts={} count_layers={} count_experts={}",
                num_layers,
                num_experts,
                count_layers,
                count_experts_per_layer,
            );
            return Self::disabled();
        }

        let Some(summary_plan) = Self::build_blend_plan(
            counts,
            count_layers,
            count_experts_per_layer,
            hcs,
            PROMPT_HCS_DEFAULT_RETAIN_PCT,
            0,
        ) else {
            log::warn!("PROMPT HCS SHADOW disabled: failed to build default blend plan");
            return Self::disabled();
        };

        let mut variants = Vec::new();
        for retain_pct in Self::RETAIN_PCTS {
            let Some(plan) = Self::build_blend_plan(
                counts,
                count_layers,
                count_experts_per_layer,
                hcs,
                retain_pct,
                0,
            ) else {
                continue;
            };

            log::info!(
                "PROMPT HCS SHADOW BUILD retain_pct={} prompt_tokens={} hard_resident={} soft_capacity={} heatmap_retained={} prompt_ranked={} backfilled={} candidate_total={} count_layers={} count_experts={}",
                plan.retain_pct,
                prompt_tokens,
                plan.hard_resident,
                plan.soft_capacity,
                plan.heatmap_retained,
                plan.prompt_ranked,
                plan.backfilled,
                plan.candidate_resident.iter().filter(|&&v| v).count(),
                count_layers,
                count_experts_per_layer,
            );

            variants.push(PromptHcsShadowVariant {
                retain_pct: plan.retain_pct,
                heatmap_retained: plan.heatmap_retained,
                prompt_ranked: plan.prompt_ranked,
                backfilled: plan.backfilled,
                candidate_resident: plan.candidate_resident,
                shadow_hcs: 0,
                shadow_cold: 0,
                extra_hits: 0,
                lost_hits: 0,
                layer_stats: vec![PromptHcsShadowLayerStats::default(); num_layers],
            });
        }

        log::info!(
            "PROMPT HCS SHADOW BUILD variants={} prompt_tokens={} hard_resident={} soft_capacity={} prompt_ranked_candidates={} heatmap_candidates={} count_layers={} count_experts={}",
            variants.len(),
            prompt_tokens,
            summary_plan.hard_resident,
            summary_plan.soft_capacity,
            summary_plan.prompt_ranked_candidates,
            summary_plan.heatmap_candidates,
            count_layers,
            count_experts_per_layer,
        );

        Self {
            enabled: true,
            prompt_tokens,
            num_layers,
            num_experts_per_layer: num_experts,
            soft_capacity: summary_plan.soft_capacity,
            hard_resident: summary_plan.hard_resident,
            selected_total: 0,
            actual_hcs: 0,
            actual_cold: 0,
            variants,
        }
    }

    fn reset_counts(&mut self) {
        self.selected_total = 0;
        self.actual_hcs = 0;
        self.actual_cold = 0;
        for variant in &mut self.variants {
            variant.shadow_hcs = 0;
            variant.shadow_cold = 0;
            variant.extra_hits = 0;
            variant.lost_hits = 0;
            for st in &mut variant.layer_stats {
                *st = PromptHcsShadowLayerStats::default();
            }
        }
    }

    fn record(&mut self, layer_idx: usize, expert_idx: usize, actual_hit: bool) {
        if !self.enabled || layer_idx >= self.num_layers || expert_idx >= self.num_experts_per_layer
        {
            return;
        }
        let idx = layer_idx * self.num_experts_per_layer + expert_idx;

        self.selected_total += 1;
        if actual_hit {
            self.actual_hcs += 1;
        } else {
            self.actual_cold += 1;
        }

        for variant in &mut self.variants {
            let shadow_hit = variant
                .candidate_resident
                .get(idx)
                .copied()
                .unwrap_or(false);
            if shadow_hit {
                variant.shadow_hcs += 1;
            } else {
                variant.shadow_cold += 1;
            }
            if !actual_hit && shadow_hit {
                variant.extra_hits += 1;
            } else if actual_hit && !shadow_hit {
                variant.lost_hits += 1;
            }

            if let Some(st) = variant.layer_stats.get_mut(layer_idx) {
                st.selected += 1;
                if shadow_hit {
                    st.shadow_hcs += 1;
                }
                if !actual_hit && shadow_hit {
                    st.extra_hits += 1;
                } else if actual_hit && !shadow_hit {
                    st.lost_hits += 1;
                }
            }
        }
    }

    fn emit_summary(&self, generated_tokens: usize) {
        if !self.enabled || self.selected_total == 0 {
            return;
        }
        let tokens = generated_tokens.max(1) as f64;
        let actual_cold_per_tok = self.actual_cold as f64 / tokens;

        eprintln!("  \x1b[36m┌─────────────────────────────────────────────────┐\x1b[0m");
        eprintln!(
            "  \x1b[36m│\x1b[0m  PROMPT HCS SHADOW (exact execution)         \x1b[36m│\x1b[0m"
        );
        eprintln!("  \x1b[36m├─────────────────────────────────────────────────┤\x1b[0m");
        eprintln!(
            "  \x1b[36m│\x1b[0m  Prompt: {} tokens | hard {} | soft cap {}      \x1b[36m│\x1b[0m",
            self.prompt_tokens, self.hard_resident, self.soft_capacity
        );
        eprintln!(
            "  \x1b[36m│\x1b[0m  Actual cold: {:.1}/tok | variants {}             \x1b[36m│\x1b[0m",
            actual_cold_per_tok,
            self.variants.len()
        );
        for variant in &self.variants {
            let shadow_cold_per_tok = variant.shadow_cold as f64 / tokens;
            let net_hits = variant.shadow_hcs as i64 - self.actual_hcs as i64;
            let net_hits_per_tok = net_hits as f64 / tokens;
            let cold_reduction_pct = if self.actual_cold > 0 {
                (self.actual_cold as i64 - variant.shadow_cold as i64) as f64
                    / self.actual_cold as f64
                    * 100.0
            } else {
                0.0
            };
            eprintln!("  \x1b[36m│\x1b[0m  Keep {:>2}% heatmap: shadow {:.1}/tok net {:+.1} ({:+.1}%) \x1b[36m│\x1b[0m",
                variant.retain_pct, shadow_cold_per_tok, net_hits_per_tok, cold_reduction_pct);
        }
        eprintln!("  \x1b[36m└─────────────────────────────────────────────────┘\x1b[0m");

        for variant in &self.variants {
            let shadow_cold_per_tok = variant.shadow_cold as f64 / tokens;
            let extra_hits_per_tok = variant.extra_hits as f64 / tokens;
            let lost_hits_per_tok = variant.lost_hits as f64 / tokens;
            let net_hits = variant.shadow_hcs as i64 - self.actual_hcs as i64;
            let net_hits_per_tok = net_hits as f64 / tokens;
            let cold_reduction_pct = if self.actual_cold > 0 {
                (self.actual_cold as i64 - variant.shadow_cold as i64) as f64
                    / self.actual_cold as f64
                    * 100.0
            } else {
                0.0
            };
            let mut layer_top: Vec<(usize, u64, u64, u64)> = variant
                .layer_stats
                .iter()
                .enumerate()
                .filter_map(|(idx, st)| {
                    if st.extra_hits == 0 && st.lost_hits == 0 {
                        None
                    } else {
                        Some((idx, st.extra_hits, st.lost_hits, st.selected))
                    }
                })
                .collect();
            layer_top.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.2.cmp(&b.2)));
            let top_layers: Vec<String> = layer_top
                .iter()
                .take(8)
                .map(|(layer, extra, lost, selected)| {
                    format!("L{}:+{} -{} sel={}", layer, extra, lost, selected)
                })
                .collect();
            log::info!(
                "PROMPT HCS SHADOW SUMMARY retain_pct={} generated={} prompt_tokens={} selected={} actual_hcs={} actual_cold={} shadow_hcs={} shadow_cold={} extra_hits={} lost_hits={} actual_cold_per_tok={:.3} shadow_cold_per_tok={:.3} extra_hits_per_tok={:.3} lost_hits_per_tok={:.3} net_hits={} net_hits_per_tok={:.3} cold_reduction_pct={:.3} hard_resident={} soft_capacity={} heatmap_retained={} prompt_ranked={} backfilled={} top_layers=[{}]",
                variant.retain_pct,
                generated_tokens,
                self.prompt_tokens,
                self.selected_total,
                self.actual_hcs,
                self.actual_cold,
                variant.shadow_hcs,
                variant.shadow_cold,
                variant.extra_hits,
                variant.lost_hits,
                actual_cold_per_tok,
                shadow_cold_per_tok,
                extra_hits_per_tok,
                lost_hits_per_tok,
                net_hits,
                net_hits_per_tok,
                cold_reduction_pct,
                self.hard_resident,
                self.soft_capacity,
                variant.heatmap_retained,
                variant.prompt_ranked,
                variant.backfilled,
                top_layers.join("; "),
            );
        }
    }
}

fn prompt_hcs_reload_enabled() -> bool {
    env_enabled_default("KRASIS_PROMPT_HCS_RELOAD", true)
}

fn prompt_hcs_reload_retain_pct() -> usize {
    env_usize(
        "KRASIS_PROMPT_HCS_RETAIN_PCT",
        PROMPT_HCS_DEFAULT_RETAIN_PCT,
    )
    .clamp(0, 100)
}

fn pack_soft_host_slot(
    hcs: &mut HcsState,
    moe_layers: &[Option<MoeLayerData>],
    slot: usize,
    layer_idx: usize,
    expert_idx: usize,
) -> bool {
    let spc = hcs.soft_slots_per_chunk;
    let slot_size = hcs.soft_slot_size;
    if spc == 0 || slot_size == 0 || slot >= hcs.soft_num_slots {
        return false;
    }
    let Some(moe) = moe_layers.get(layer_idx).and_then(|m| m.as_ref()) else {
        return false;
    };
    let Some(expert) = moe.experts.get(expert_idx) else {
        return false;
    };
    let chunk_idx = slot / spc;
    if chunk_idx >= hcs.soft_host_chunks.len() {
        return false;
    }
    let offset_in_chunk = slot % spc;
    let host_offset = offset_in_chunk * slot_size;
    let w13p_off = 0usize;
    let w13s_off = expert.w13_packed_bytes;
    let w2p_off = w13s_off + expert.w13_scales_bytes;
    let w2s_off = w2p_off + expert.w2_packed_bytes;
    let needed = w2s_off.saturating_add(expert.w2_scales_bytes);
    if needed > slot_size {
        log::warn!(
            "PROMPT HCS RELOAD: slot pack skipped L{}E{} needs {} bytes > slot_size {}",
            layer_idx,
            expert_idx,
            needed,
            slot_size,
        );
        return false;
    }
    unsafe {
        let dst = hcs.soft_host_chunks[chunk_idx]
            .as_mut_ptr()
            .add(host_offset);
        std::ptr::copy_nonoverlapping(
            expert.w13_packed_ptr as *const u8,
            dst.add(w13p_off),
            expert.w13_packed_bytes,
        );
        std::ptr::copy_nonoverlapping(
            expert.w13_scales_ptr as *const u8,
            dst.add(w13s_off),
            expert.w13_scales_bytes,
        );
        std::ptr::copy_nonoverlapping(
            expert.w2_packed_ptr as *const u8,
            dst.add(w2p_off),
            expert.w2_packed_bytes,
        );
        std::ptr::copy_nonoverlapping(
            expert.w2_scales_ptr as *const u8,
            dst.add(w2s_off),
            expert.w2_scales_bytes,
        );
    }
    true
}

fn apply_prompt_hcs_reload_blend(
    hcs: &mut HcsState,
    moe_layers: &[Option<MoeLayerData>],
    counts: &[u64],
    count_layers: usize,
    count_experts_per_layer: usize,
    prompt_tokens: usize,
    target_chunks: usize,
) -> usize {
    if !prompt_hcs_reload_enabled()
        || counts.is_empty()
        || hcs.soft_num_slots == 0
        || hcs.soft_slots_per_chunk == 0
    {
        return 0;
    }
    let use_host_mirror = hcs.soft_host_mode == HcsSoftHostMode::Mirror;
    let retain_pct = prompt_hcs_reload_retain_pct();
    let spc = hcs.soft_slots_per_chunk;
    let requested_retain_slots = (hcs.soft_num_slots.saturating_mul(retain_pct) + 99) / 100;
    let retain_chunks = if requested_retain_slots == 0 {
        0
    } else {
        ((requested_retain_slots + spc - 1) / spc).min(hcs.soft_total_chunks)
    };
    let retained_chunks = retain_chunks.min(target_chunks);
    let min_heatmap_slots = retained_chunks.saturating_mul(spc).min(hcs.soft_num_slots);
    let Some(plan) = PromptHcsShadowStats::build_blend_plan(
        counts,
        count_layers,
        count_experts_per_layer,
        hcs,
        retain_pct,
        min_heatmap_slots,
    ) else {
        log::warn!(
            "PROMPT HCS RELOAD disabled for request: failed to build blend plan prompt_tokens={} count_layers={} count_experts={}",
            prompt_tokens,
            count_layers,
            count_experts_per_layer,
        );
        return 0;
    };

    if prompt_hcs_log_enabled() {
        eprintln!(
            "[PROMPT-HCS] reload plan retain_pct={} effective_heatmap_slots={} prompt_tokens={} target_chunks={} loaded_chunks={} prompt_ranked={} backfilled={}",
            retain_pct,
            min_heatmap_slots,
            prompt_tokens,
            target_chunks,
            hcs.soft_chunks_loaded,
            plan.prompt_ranked,
            plan.backfilled,
        );
    }

    let loaded_slots = hcs
        .soft_chunks_loaded
        .saturating_mul(spc)
        .min(hcs.soft_num_slots);
    let target_slots = target_chunks
        .saturating_mul(spc)
        .min(hcs.soft_num_slots)
        .min(plan.ranking.len());
    if target_slots <= loaded_slots {
        return 0;
    }

    let mut changed_slots = 0usize;
    let mut repacked_slots = 0usize;
    for slot in loaded_slots..target_slots {
        let desired = plan.ranking[slot];
        let current = hcs.soft_ranking.get(slot).copied();
        if current == Some(desired) {
            continue;
        }
        changed_slots += 1;
        if !use_host_mirror {
            repacked_slots += 1;
        } else if pack_soft_host_slot(hcs, moe_layers, slot, desired.0, desired.1) {
            repacked_slots += 1;
        } else {
            panic!(
                "PROMPT HCS RELOAD failed to repack soft slot {} as L{}E{}; refusing to continue with mismatched ranking/host contents",
                slot,
                desired.0,
                desired.1,
            );
        }
    }

    if hcs.soft_ranking.len() == plan.ranking.len() {
        hcs.soft_ranking = plan.ranking;
    } else {
        log::warn!(
            "PROMPT HCS RELOAD: ranking length mismatch current={} planned={}; keeping current ranking",
            hcs.soft_ranking.len(),
            plan.ranking.len(),
        );
        return 0;
    }

    log::info!(
        "PROMPT HCS RELOAD applied: retain_pct={} effective_heatmap_slots={} prompt_tokens={} target_chunks={} loaded_chunks={} changed_slots={} repacked_slots={} host_mode={} heatmap_retained={} prompt_ranked={} backfilled={} prompt_candidates={} heatmap_candidates={}",
        retain_pct,
        min_heatmap_slots,
        prompt_tokens,
        target_chunks,
        hcs.soft_chunks_loaded,
        changed_slots,
        repacked_slots,
        hcs.soft_host_mode.label(),
        plan.heatmap_retained,
        plan.prompt_ranked,
        plan.backfilled,
        plan.prompt_ranked_candidates,
        plan.heatmap_candidates,
    );
    if prompt_hcs_log_enabled() {
        eprintln!(
            "[PROMPT-HCS] reload applied retain_pct={} changed_slots={} repacked_slots={} target_chunks={} loaded_chunks={}",
            retain_pct,
            changed_slots,
            repacked_slots,
            target_chunks,
            hcs.soft_chunks_loaded,
        );
    }
    repacked_slots
}

fn sync_hcs_route_pointer_updates(device: &Arc<CudaDevice>, reason: &str, updates: usize) -> bool {
    if updates == 0 {
        return true;
    }
    if !bind_hcs_route_pointer_device(device, reason) {
        return false;
    }
    let err = unsafe { cuda_sys::lib().cuStreamSynchronize(std::ptr::null_mut()) };
    if err == cuda_sys::CUresult::CUDA_SUCCESS {
        log::debug!(
            "GPU route sync: synchronized {} HCS pointer-table updates ({})",
            updates,
            reason,
        );
        true
    } else {
        log::error!(
            "GPU route sync: HCS pointer-table synchronization failed after {} updates ({}): {:?}",
            updates,
            reason,
            err,
        );
        false
    }
}

fn parse_polar4_norm_correction_mode() -> i32 {
    match std::env::var("KRASIS_POLAR4_NORM_CORRECTION") {
        Ok(v) => match v.trim().to_ascii_lowercase().as_str() {
            "" | "0" | "false" | "no" | "off" | "none" => 0,
            "1" | "true" | "yes" | "on" | "kv" | "both" => 3,
            "k" | "key" | "keys" => 1,
            "v" | "value" | "values" => 2,
            other => {
                log::warn!(
                    "Unrecognized KRASIS_POLAR4_NORM_CORRECTION='{}'; disabling Polar4 norm correction",
                    other
                );
                0
            }
        },
        Err(_) => 0,
    }
}

#[derive(Clone, Copy)]
struct TraceRange {
    start: usize,
    end: usize,
}

impl TraceRange {
    fn contains(&self, value: usize) -> bool {
        value >= self.start && value <= self.end
    }
}

#[derive(Clone)]
struct DecodeTraceConfig {
    steps: Option<TraceRange>,
    layers: Option<TraceRange>,
    components: Option<HashSet<String>>,
    experts: Option<HashSet<usize>>,
    sample_values: usize,
    max_elems: usize,
    dump_dir: Option<String>,
}

impl DecodeTraceConfig {
    fn from_env() -> Option<Self> {
        let enabled = std::env::var("KRASIS_TRACE")
            .map(|v| v == "1")
            .unwrap_or(false);
        if !enabled {
            return None;
        }

        let components = std::env::var("KRASIS_TRACE_COMPONENTS")
            .ok()
            .and_then(|raw| {
                let set: HashSet<String> = raw
                    .split(',')
                    .map(|s| s.trim().to_ascii_lowercase())
                    .filter(|s| !s.is_empty())
                    .collect();
                if set.is_empty() {
                    None
                } else {
                    Some(set)
                }
            });

        Some(Self {
            steps: parse_trace_range(std::env::var("KRASIS_TRACE_STEPS").ok().as_deref()),
            layers: parse_trace_range(std::env::var("KRASIS_TRACE_LAYERS").ok().as_deref()),
            components,
            experts: parse_trace_id_set(std::env::var("KRASIS_TRACE_EXPERTS").ok().as_deref()),
            sample_values: std::env::var("KRASIS_TRACE_VALUES")
                .ok()
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(8),
            max_elems: std::env::var("KRASIS_TRACE_ELEMS")
                .ok()
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(2048),
            dump_dir: std::env::var("KRASIS_TRACE_DUMP_DIR")
                .ok()
                .filter(|s| !s.trim().is_empty()),
        })
    }

    fn allows_step(&self, step: usize) -> bool {
        self.steps.map(|r| r.contains(step)).unwrap_or(true)
    }

    fn allows_layer(&self, layer: usize) -> bool {
        self.layers.map(|r| r.contains(layer)).unwrap_or(true)
    }

    fn allows_component(&self, component: &str) -> bool {
        let Some(filters) = self.components.as_ref() else {
            return true;
        };
        let component = component.to_ascii_lowercase();
        if filters.contains("decode") && component != "config_contract" {
            return true;
        }
        if filters.contains("all") || filters.contains(&component) {
            return true;
        }
        if let Some((prefix, _)) = component.split_once('_') {
            return filters.contains(prefix);
        }
        false
    }

    fn should_emit(&self, step: usize, layer: Option<usize>, component: &str) -> bool {
        self.allows_step(step)
            && layer.map(|v| self.allows_layer(v)).unwrap_or(true)
            && self.allows_component(component)
    }

    fn explicitly_enables(&self, component: &str) -> bool {
        self.components
            .as_ref()
            .map(|filters| filters.contains(&component.to_ascii_lowercase()))
            .unwrap_or(false)
    }

    fn allows_expert(&self, expert: usize) -> bool {
        self.experts
            .as_ref()
            .map(|experts| experts.contains(&expert))
            .unwrap_or(true)
    }
}

fn parse_trace_range(raw: Option<&str>) -> Option<TraceRange> {
    let raw = raw?.trim();
    if raw.is_empty() || raw.eq_ignore_ascii_case("all") {
        return None;
    }
    if let Some((start, end)) = raw.split_once('-') {
        let start = start.trim().parse::<usize>().ok()?;
        let end = end.trim().parse::<usize>().ok()?;
        return Some(TraceRange {
            start,
            end: end.max(start),
        });
    }
    let value = raw.parse::<usize>().ok()?;
    Some(TraceRange {
        start: value,
        end: value,
    })
}

fn parse_trace_id_set(raw: Option<&str>) -> Option<HashSet<usize>> {
    let raw = raw?.trim();
    if raw.is_empty() || raw.eq_ignore_ascii_case("all") {
        return None;
    }
    let set: HashSet<usize> = raw
        .split(',')
        .filter_map(|s| s.trim().parse::<usize>().ok())
        .collect();
    if set.is_empty() {
        None
    } else {
        Some(set)
    }
}

fn trace_format_sample(values: &[f32]) -> String {
    values
        .iter()
        .map(|v| format!("{:.6}", v))
        .collect::<Vec<_>>()
        .join(",")
}

fn sanitize_trace_label(label: &str) -> String {
    let mut out = String::with_capacity(label.len().min(48));
    for ch in label.chars() {
        if out.len() >= 48 {
            break;
        }
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    if out.is_empty() {
        "decode".to_string()
    } else {
        out
    }
}

fn trace_emit_mark(
    trace: Option<&DecodeTraceConfig>,
    step: usize,
    position: usize,
    token_id: usize,
    layer: Option<usize>,
    component: &str,
    message: &str,
) {
    let Some(trace) = trace else {
        return;
    };
    if !trace.should_emit(step, layer, component) {
        return;
    }
    let layer_s = layer
        .map(|v| v.to_string())
        .unwrap_or_else(|| "-".to_string());
    eprintln!(
        "[KRASIS-TRACE] event=mark step={} pos={} tok={} layer={} component={} {}",
        step, position, token_id, layer_s, component, message
    );
}

fn trace_emit_global_mark(trace: Option<&DecodeTraceConfig>, component: &str, message: &str) {
    let Some(trace) = trace else {
        return;
    };
    if !trace.allows_component(component) {
        return;
    }
    eprintln!(
        "[KRASIS-TRACE] event=mark scope=global component={} {}",
        component, message,
    );
}

fn find_first_byte_mismatch(actual: &[u8], expected: &[u8]) -> Option<(usize, u8, u8)> {
    actual
        .iter()
        .zip(expected.iter())
        .enumerate()
        .find_map(|(idx, (&a, &e))| if a != e { Some((idx, a, e)) } else { None })
}

fn trace_emit_f32(
    trace: Option<&DecodeTraceConfig>,
    step: usize,
    position: usize,
    token_id: usize,
    layer: Option<usize>,
    component: &str,
    tensor: &str,
    ptr: u64,
    n: usize,
    device: &Arc<CudaDevice>,
) {
    let Some(trace) = trace else {
        return;
    };
    if !trace.should_emit(step, layer, component) {
        return;
    }
    let _ = device.synchronize();
    let count = n.min(trace.max_elems).max(1);
    let mut buf = vec![0.0f32; count];
    unsafe {
        let _ = cuda_sys::lib().cuMemcpyDtoH_v2(
            buf.as_mut_ptr() as *mut std::ffi::c_void,
            ptr,
            count * 4,
        );
    }
    let mut min_v = f32::INFINITY;
    let mut max_v = f32::NEG_INFINITY;
    let mut sum = 0.0f64;
    let mut l2 = 0.0f64;
    let mut nan = 0usize;
    let mut inf = 0usize;
    for &v in &buf {
        if v.is_nan() {
            nan += 1;
            continue;
        }
        if v.is_infinite() {
            inf += 1;
            continue;
        }
        min_v = min_v.min(v);
        max_v = max_v.max(v);
        let vf = v as f64;
        sum += vf;
        l2 += vf * vf;
    }
    let finite = count.saturating_sub(nan + inf).max(1);
    let sample = trace_format_sample(&buf[..buf.len().min(trace.sample_values)]);
    let layer_s = layer
        .map(|v| v.to_string())
        .unwrap_or_else(|| "-".to_string());
    eprintln!(
        "[KRASIS-TRACE] event=tensor step={} pos={} tok={} layer={} component={} tensor={} dtype=f32 n={} sample=[{}] l2={:.6} mean={:.6} min={:.6} max={:.6} nan={} inf={}",
        step,
        position,
        token_id,
        layer_s,
        component,
        tensor,
        count,
        sample,
        l2.sqrt(),
        sum / finite as f64,
        min_v,
        max_v,
        nan,
        inf,
    );
}

