#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct DsaTopkPlan {
    pub(crate) context: usize,
    pub(crate) selected: usize,
    pub(crate) sort_width: usize,
    pub(crate) initial_runs: usize,
    pub(crate) merge_passes: usize,
    pub(crate) candidate_capacity: usize,
    pub(crate) shared_bytes: usize,
}

const DSA_TOPK_RADIX_THREADS: usize = 256;
const DSA_TOPK_RADIX_ITEMS_PER_THREAD: usize = 4;
const DSA_TOPK_RADIX_CAPACITY: usize = DSA_TOPK_RADIX_THREADS * DSA_TOPK_RADIX_ITEMS_PER_THREAD;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DsaGraphScoreBackend {
    FixedCapacityTensorCore,
    LiveFused,
}

pub(crate) fn plan_dsa_topk(context: usize, configured_topk: usize) -> Result<DsaTopkPlan, String> {
    if context == 0 {
        return Err("DSA top-k requires positive context".to_string());
    }
    if configured_topk == 0 {
        return Err("DSA top-k requires positive configured top-k".to_string());
    }
    let selected = configured_topk.min(context);
    let padded_selected = selected
        .checked_next_power_of_two()
        .ok_or_else(|| format!("DSA top-k {} power-of-two overflow", selected))?;
    let sort_width = if context <= selected {
        context
            .checked_next_power_of_two()
            .ok_or_else(|| format!("DSA context {} power-of-two overflow", context))?
    } else {
        padded_selected
            .checked_mul(2)
            .ok_or_else(|| format!("DSA top-k {} merge-width overflow", selected))?
    };
    let initial_runs = context.div_ceil(sort_width);
    let candidate_capacity = if initial_runs > 1 {
        initial_runs.checked_mul(selected).ok_or_else(|| {
            format!(
                "DSA top-k candidate capacity overflow: runs={} selected={}",
                initial_runs, selected
            )
        })?
    } else {
        0
    };
    let mut merge_passes = 0usize;
    let mut runs = initial_runs;
    while runs > 1 {
        runs = runs.div_ceil(2);
        merge_passes += 1;
    }
    let shared_bytes = sort_width
        .checked_mul(std::mem::size_of::<f32>() + std::mem::size_of::<i32>())
        .ok_or_else(|| format!("DSA top-k shared-memory overflow: width={}", sort_width))?;
    Ok(DsaTopkPlan {
        context,
        selected,
        sort_width,
        initial_runs,
        merge_passes,
        candidate_capacity,
        shared_bytes,
    })
}

// GLM DSA defines its index-key LayerNorm independently of the model-wide
// RMSNorm epsilon; the checkpoint architecture source fixes this semantic
// value at 1e-6 rather than exposing it as a model or hardware tuning knob.
const DSA_INDEXER_LAYER_NORM_EPS: f32 = 1e-6;

fn validate_dsa_owner_weight_contract(
    weights: &[GpuWeight],
    registration: &DsaIndexerRegistration,
    weight_ids: DsaIndexerOwnerWeightIds,
    max_context_tokens: usize,
) -> Result<(usize, usize, usize, usize, usize), String> {
    if max_context_tokens == 0 {
        return Err(format!(
            "DSA owner layer {} requires positive max_context_tokens",
            registration.owner_layer_idx
        ));
    }
    let query_width = registration
        .index_n_heads
        .checked_mul(registration.index_head_dim)
        .ok_or_else(|| {
            format!(
                "DSA owner layer {} query width overflow",
                registration.owner_layer_idx
            )
        })?;
    let expected = [
        (
            "wq_b",
            weight_ids.wq_b,
            query_width,
            registration.q_lora_rank,
        ),
        (
            "wk",
            weight_ids.wk,
            registration.index_head_dim,
            registration.hidden_size,
        ),
        (
            "weights_proj",
            weight_ids.weights_proj,
            registration.index_n_heads,
            registration.hidden_size,
        ),
        (
            "k_norm_weight",
            weight_ids.k_norm_weight,
            1,
            registration.index_head_dim,
        ),
        (
            "k_norm_bias",
            weight_ids.k_norm_bias,
            1,
            registration.index_head_dim,
        ),
    ];
    for (name, wid, rows, cols) in expected {
        let weight = weights.get(wid).ok_or_else(|| {
            format!(
                "DSA owner layer {} {} weight id {} is not registered",
                registration.owner_layer_idx, name, wid
            )
        })?;
        if weight.ptr == 0 {
            return Err(format!(
                "DSA owner layer {} {} has a null device pointer",
                registration.owner_layer_idx, name
            ));
        }
        if weight.dtype != 0 {
            return Err(format!(
                "DSA owner layer {} {} must be BF16, got dtype code {}",
                registration.owner_layer_idx, name, weight.dtype
            ));
        }
        if weight.rows != rows || weight.cols != cols {
            return Err(format!(
                "DSA owner layer {} {} shape [{}, {}] != expected [{}, {}]",
                registration.owner_layer_idx, name, weight.rows, weight.cols, rows, cols
            ));
        }
    }
    match (
        registration.index_kpool_compress,
        weight_ids.kpool_ape,
        weight_ids.kpool_gate,
    ) {
        (true, Some(ape_wid), Some(gate_wid)) => {
            for (name, wid, rows, cols) in [
                (
                    "index_kpool_compress_ape",
                    ape_wid,
                    registration.index_kpool,
                    registration.index_head_dim,
                ),
                (
                    "index_kpool_compress_gate",
                    gate_wid,
                    registration.index_head_dim,
                    registration.hidden_size,
                ),
            ] {
                let weight = weights.get(wid).ok_or_else(|| {
                    format!(
                        "DSA owner layer {} {} weight id {} is not registered",
                        registration.owner_layer_idx, name, wid
                    )
                })?;
                if weight.ptr == 0
                    || weight.dtype != 0
                    || weight.rows != rows
                    || weight.cols != cols
                {
                    return Err(format!(
                        "DSA owner layer {} {} contract mismatch: ptr=0x{:x} dtype={} shape=[{}, {}], expected BF16 [{}, {}]",
                        registration.owner_layer_idx,
                        name,
                        weight.ptr,
                        weight.dtype,
                        weight.rows,
                        weight.cols,
                        rows,
                        cols
                    ));
                }
            }
        }
        (true, _, _) => {
            return Err(format!(
                "DSA owner layer {} compressed k-pool weights are incomplete",
                registration.owner_layer_idx
            ));
        }
        (false, None, None) => {}
        (false, _, _) => {
            return Err(format!(
                "DSA owner layer {} supplied k-pool weights while compression is disabled",
                registration.owner_layer_idx
            ));
        }
    }
    let key_cache_elems = max_context_tokens
        .checked_mul(registration.index_head_dim)
        .ok_or_else(|| {
            format!(
                "DSA owner layer {} key-cache size overflow: context={} head_dim={}",
                registration.owner_layer_idx, max_context_tokens, registration.index_head_dim
            )
        })?;
    let (topk_capacity, gate_cache_elems, pool_key_elems, pool_topk_capacity) =
        if registration.index_kpool_compress {
            let pool_capacity = dsa_score_context_capacity(registration, max_context_tokens);
            let selected_capacity = dsa_expanded_topk_capacity(registration, max_context_tokens)?;
            (
                selected_capacity,
                key_cache_elems,
                pool_capacity
                    .checked_mul(registration.index_head_dim)
                    .ok_or_else(|| "DSA k-pool key-cache size overflow".to_string())?,
                (registration.index_topk / registration.index_kpool).min(pool_capacity),
            )
        } else {
            (registration.index_topk.min(max_context_tokens), 0, 0, 0)
        };
    Ok((
        key_cache_elems,
        topk_capacity,
        gate_cache_elems,
        pool_key_elems,
        pool_topk_capacity,
    ))
}

/// DSA k-pool scores one row per complete or partial pool while retaining the
/// uncompressed key/gate history at the full logical context length.  Keep
/// these two capacities distinct: the shared score workspace is pool-sized,
/// whereas owner caches and prefill admission remain token-sized.
fn dsa_score_context_capacity(
    registration: &DsaIndexerRegistration,
    logical_context_tokens: usize,
) -> usize {
    if registration.index_kpool_compress {
        logical_context_tokens.div_ceil(registration.index_kpool)
    } else {
        logical_context_tokens
    }
}

fn dsa_expanded_topk_capacity(
    registration: &DsaIndexerRegistration,
    logical_context_tokens: usize,
) -> Result<usize, String> {
    let selected = registration.index_topk.min(logical_context_tokens);
    if registration.index_kpool_compress {
        selected
            .checked_add(registration.index_kpool - 1)
            .ok_or_else(|| "DSA k-pool selected capacity overflow".to_string())
    } else {
        Ok(selected)
    }
}

#[allow(clippy::too_many_arguments)]
fn validate_dsa_indexer_registration(
    layer_idx: usize,
    owner_layer_idx: usize,
    owner_weights_present: bool,
    index_topk: usize,
    index_head_dim: usize,
    index_n_heads: usize,
    qk_rope_head_dim: usize,
    index_topk_freq: usize,
    index_skip_topk_offset: usize,
    q_lora_rank: usize,
    hidden_size: usize,
    rope_interleave: bool,
    index_kpool: usize,
    index_kpool_compress: bool,
    index_kpool_always_select_tail: bool,
) -> Result<DsaIndexerRegistration, String> {
    if owner_layer_idx > layer_idx {
        return Err(format!(
            "DSA layer {} cannot share future indexer owner {}",
            layer_idx, owner_layer_idx
        ));
    }
    for (name, value) in [
        ("index_topk", index_topk),
        ("index_head_dim", index_head_dim),
        ("index_n_heads", index_n_heads),
        ("q_lora_rank", q_lora_rank),
        ("hidden_size", hidden_size),
    ] {
        if value == 0 {
            return Err(format!(
                "DSA layer {} requires positive {}, got 0",
                layer_idx, name
            ));
        }
    }
    // `index_topk_freq` and `index_skip_topk_offset` are legacy inputs used by
    // model configuration code to synthesize an IndexShare schedule.  The Rust
    // runtime receives the already-resolved owner for every DSA layer, so a
    // checkpoint with an explicit `indexer_types` schedule truthfully leaves
    // these legacy synthesis fields at zero.  Keep recording them for
    // provenance and cross-layer consistency, but do not treat zero as a
    // missing executable dimension.
    if index_head_dim % 2 != 0 || qk_rope_head_dim % 2 != 0 {
        return Err(format!(
            "DSA layer {} index_head_dim {} and qk_rope_head_dim {} must be even for RoPE",
            layer_idx, index_head_dim, qk_rope_head_dim
        ));
    }
    if qk_rope_head_dim > index_head_dim {
        return Err(format!(
            "DSA layer {} qk_rope_head_dim {} exceeds index_head_dim {}",
            layer_idx, qk_rope_head_dim, index_head_dim
        ));
    }
    if index_kpool_compress {
        if index_kpool == 0 || index_topk % index_kpool != 0 {
            return Err(format!(
                "DSA layer {} compressed k-pool requires positive pool size dividing top-k, got pool={} topk={}",
                layer_idx, index_kpool, index_topk
            ));
        }
        if !index_kpool_always_select_tail {
            return Err(format!(
                "DSA layer {} compressed k-pool requires visible-tail selection",
                layer_idx
            ));
        }
    } else if index_kpool != 0 || index_kpool_always_select_tail {
        return Err(format!(
            "DSA layer {} has inconsistent disabled k-pool contract: pool={} tail={}",
            layer_idx, index_kpool, index_kpool_always_select_tail
        ));
    }
    index_n_heads.checked_mul(index_head_dim).ok_or_else(|| {
        format!(
            "DSA layer {} index projection width overflow: heads={} head_dim={}",
            layer_idx, index_n_heads, index_head_dim
        )
    })?;

    let is_owner = owner_layer_idx == layer_idx;
    if owner_weights_present != is_owner {
        return Err(if is_owner {
            format!(
                "DSA indexer owner layer {} has no validated owner weights",
                layer_idx
            )
        } else {
            format!(
                "DSA shared layer {} duplicates weights owned by layer {}",
                layer_idx, owner_layer_idx
            )
        });
    }

    Ok(DsaIndexerRegistration {
        owner_layer_idx,
        owner_weights_present,
        index_topk,
        index_head_dim,
        index_n_heads,
        qk_rope_head_dim,
        index_topk_freq,
        index_skip_topk_offset,
        q_lora_rank,
        hidden_size,
        rope_interleave,
        index_kpool,
        index_kpool_compress,
        index_kpool_always_select_tail,
    })
}

fn dsa_registered_layers(graph: &GpuDecodeGraph) -> Vec<usize> {
    graph
        .layers
        .iter()
        .enumerate()
        .filter_map(|(layer_idx, layer)| layer.dsa_indexer.as_ref().map(|_| layer_idx))
        .collect()
}

fn validate_dsa_runtime_registration(
    registrations: &[&DsaIndexerRegistration],
    registered_layer_indices: &[usize],
    expected_layer_indices: &[usize],
    runtime_context_tokens: usize,
) -> Result<usize, String> {
    let first = registrations
        .first()
        .ok_or_else(|| "DSA graph flag is set but no layer registrations exist".to_string())?;
    if runtime_context_tokens == 0 {
        return Err("DSA runtime requires a positive context".to_string());
    }
    let registered = registered_layer_indices
        .iter()
        .copied()
        .collect::<std::collections::BTreeSet<_>>();
    let expected = expected_layer_indices
        .iter()
        .copied()
        .collect::<std::collections::BTreeSet<_>>();
    if registrations.len() != registered_layer_indices.len() || registered != expected {
        let missing = expected
            .difference(&registered)
            .copied()
            .collect::<Vec<_>>();
        let unexpected = registered
            .difference(&expected)
            .copied()
            .collect::<Vec<_>>();
        return Err(format!(
            "DSA graph registration is incomplete: {} of {} expected MLA layers registered; missing={:?} unexpected={:?}",
            registrations.len(),
            expected.len(),
            missing,
            unexpected,
        ));
    }
    let index_topk = first.index_topk;
    for registration in registrations.iter().skip(1) {
        if registration.index_topk != index_topk {
            return Err(format!(
                "DSA layers disagree on index_topk: {} != {}",
                registration.index_topk, index_topk
            ));
        }
    }
    Ok(index_topk)
}

fn validate_dsa_runtime_graph(
    graph: &GpuDecodeGraph,
    max_tokens: usize,
) -> Result<Option<(usize, usize)>, String> {
    if !graph.dsa_runtime_registered {
        return Ok(None);
    }
    let registrations = graph
        .layers
        .iter()
        .filter_map(|layer| layer.dsa_indexer.as_ref())
        .collect::<Vec<_>>();
    let registered_layer_indices = dsa_registered_layers(graph);
    // DSA attaches only to MLA layers.  Hybrid GLM schedules KDA and DSA in
    // one graph, so completeness is the exact set of validated MLA layers,
    // not the total transformer-layer count.  This remains fail-closed: any
    // MLA layer lacking DSA metadata, or any registration on a non-MLA layer,
    // is reported by index.
    let expected_layer_indices = graph
        .layers
        .iter()
        .enumerate()
        .filter_map(|(layer_idx, layer)| {
            matches!(layer.attn, GpuAttnConfig::MLA { .. }).then_some(layer_idx)
        })
        .collect::<Vec<_>>();
    let runtime_context_tokens = max_tokens.max(graph.kv_max_seq);
    let index_topk = validate_dsa_runtime_registration(
        &registrations,
        &registered_layer_indices,
        &expected_layer_indices,
        runtime_context_tokens,
    )?;
    if !graph.dsa_indexer_resources_finalized {
        return Err("DSA runtime resources were not finalized before prefill construction".into());
    }
    let workspace = graph
        .dsa_indexer_workspace
        .as_ref()
        .ok_or_else(|| "DSA prefill requires a full-primary indexer workspace".to_string())?;
    let owners = registrations
        .iter()
        .filter(|registration| registration.owner_weights_present)
        .map(|registration| registration.owner_layer_idx)
        .collect::<std::collections::BTreeSet<_>>();
    for owner_layer_idx in &owners {
        let registration = registrations
            .iter()
            .copied()
            .find(|registration| registration.owner_layer_idx == *owner_layer_idx)
            .ok_or_else(|| format!("DSA owner {} has no registration", owner_layer_idx))?;
        let matching_resources = graph
            .dsa_indexer_owners
            .iter()
            .filter(|resource| resource.owner_layer_idx == *owner_layer_idx)
            .collect::<Vec<_>>();
        if matching_resources.len() != 1 {
            return Err(format!(
                "DSA owner {} requires exactly one full-primary resource, found {}",
                owner_layer_idx,
                matching_resources.len()
            ));
        }
        let resource = matching_resources[0];
        if resource.max_context_tokens < runtime_context_tokens {
            return Err(format!(
                "DSA owner {} key-cache capacity {} is smaller than runtime context {}",
                owner_layer_idx, resource.max_context_tokens, runtime_context_tokens
            ));
        }
        let expected_workspace_context =
            dsa_score_context_capacity(registration, resource.max_context_tokens);
        if workspace.max_context_tokens < expected_workspace_context {
            return Err(format!(
                "DSA workspace score capacity {} is smaller than owner {} requirement {} (logical context {})",
                workspace.max_context_tokens,
                owner_layer_idx,
                expected_workspace_context,
                resource.max_context_tokens,
            ));
        }
        let expected_topk_capacity =
            dsa_expanded_topk_capacity(registration, resource.max_context_tokens)?;
        if resource.topk_capacity != expected_topk_capacity
            || resource.index_head_dim != registration.index_head_dim
        {
            return Err(format!(
                "DSA owner {} resource geometry [topk={}, head_dim={}] != registered [{}, {}]",
                owner_layer_idx,
                resource.topk_capacity,
                resource.index_head_dim,
                expected_topk_capacity,
                registration.index_head_dim
            ));
        }
    }
    if graph.dsa_indexer_owners.len() != owners.len() {
        return Err(format!(
            "DSA full-primary resource count {} != registered owner count {}",
            graph.dsa_indexer_owners.len(),
            owners.len()
        ));
    }
    Ok(Some((index_topk, runtime_context_tokens)))
}

