#[derive(Clone, Copy, Default)]
struct PeerDemandEntry {
    score: u64,
    epoch: u64,
    last_seen: u64,
}

struct PendingPeerResidencySwap {
    slot: usize,
    victim: (usize, usize),
    incoming: (usize, usize),
    started: std::time::Instant,
}

/// Live-demand residency controller owned by an expert-only peer store. One
/// replacement may be in flight at a time; this bounds background traffic and
/// makes directory publication a single-event transaction.
struct PeerDynamicTier {
    swap_stream: CudaStream,
    swap_ready_event: CudaEvent,
    pending: Option<PendingPeerResidencySwap>,
    demand: Vec<PeerDemandEntry>,
    observations: u64,
    epoch_span: u64,
    current_epoch: u64,
    last_rebalance_epoch: u64,
    transfer_cost_routes: u64,
    swaps_queued: u64,
    swaps_committed: u64,
    swap_failures: u64,
    admission_skips: u64,
    pending_skips: u64,
    bytes_copied: u64,
    total_swap_elapsed_us: f64,
    disabled_reason: Option<String>,
}

impl PeerDynamicTier {
    fn shutdown(&mut self) {
        unsafe {
            if !self.swap_stream.0.is_null() {
                let _ = cuda_sys::lib().cuStreamSynchronize(self.swap_stream.0);
            }
            if !self.swap_ready_event.0.is_null() {
                let _ = cuda_sys::lib().cuEventDestroy_v2(self.swap_ready_event.0);
                self.swap_ready_event.0 = std::ptr::null_mut();
            }
            if !self.swap_stream.0.is_null() {
                let _ = cuda_sys::lib().cuStreamDestroy_v2(self.swap_stream.0);
                self.swap_stream.0 = std::ptr::null_mut();
            }
        }
    }

    fn disable(&mut self, reason: String) {
        if self.disabled_reason.is_none() {
            log::warn!("DYNAMIC PEER DISABLED: {reason}");
            self.disabled_reason = Some(reason);
        }
    }

    fn flat_index(experts_per_layer: usize, layer: usize, expert: usize) -> Option<usize> {
        layer
            .checked_mul(experts_per_layer)
            .and_then(|index| index.checked_add(expert))
    }

    fn observe(&mut self, index: usize) -> u64 {
        self.observations = self.observations.saturating_add(1);
        self.current_epoch = self.observations / self.epoch_span.max(1);
        let Some(entry) = self.demand.get_mut(index) else {
            return 0;
        };
        let elapsed_epochs = self.current_epoch.saturating_sub(entry.epoch);
        if elapsed_epochs > 0 {
            entry.score >>= elapsed_epochs.min(u64::BITS as u64 - 1) as u32;
            entry.epoch = self.current_epoch;
        }
        entry.score = entry.score.saturating_add(1);
        entry.last_seen = self.observations;
        entry.score
    }

    fn score(&self, index: usize) -> (u64, u64) {
        let Some(entry) = self.demand.get(index) else {
            return (0, 0);
        };
        let elapsed_epochs = self.current_epoch.saturating_sub(entry.epoch);
        (
            entry.score >> elapsed_epochs.min(u64::BITS as u64 - 1) as u32,
            entry.last_seen,
        )
    }

    fn stats_json(&self) -> serde_json::Value {
        serde_json::json!({
            "enabled": self.disabled_reason.is_none(),
            "disabled_reason": self.disabled_reason,
            "observations": self.observations,
            "epoch_span": self.epoch_span,
            "current_epoch": self.current_epoch,
            "last_rebalance_epoch": self.last_rebalance_epoch,
            "transfer_cost_routes": self.transfer_cost_routes,
            "swap_pending": self.pending.is_some(),
            "swaps_queued": self.swaps_queued,
            "swaps_committed": self.swaps_committed,
            "swap_failures": self.swap_failures,
            "admission_skips": self.admission_skips,
            "pending_skips": self.pending_skips,
            "bytes_copied": self.bytes_copied,
            "average_swap_elapsed_us": if self.swaps_committed > 0 {
                self.total_swap_elapsed_us / self.swaps_committed as f64
            } else {
                0.0
            },
        })
    }
}

impl Drop for PeerDynamicTier {
    fn drop(&mut self) {
        self.shutdown();
    }
}

fn peer_selector_check_message(
    actual_ms: f64,
    predicted_peer_ms: f64,
    alternative_ms: f64,
    uncertainty_ms: f64,
) -> (bool, String) {
    let alternative_materially_better = actual_ms > alternative_ms + uncertainty_ms;
    let label = if alternative_materially_better {
        "PEER SELECTOR WARNING"
    } else {
        "PEER SELECTOR CHECK"
    };
    let suffix = if alternative_materially_better {
        "; measured result is above the alternative prediction"
    } else {
        ""
    };
    (
        alternative_materially_better,
        format!(
            "{label}: actual_ms_per_token={actual_ms:.6} predicted_peer_ms={predicted_peer_ms:.6} alternative_ms={alternative_ms:.6} uncertainty_ms={uncertainty_ms:.6}{suffix}"
        ),
    )
}

fn measured_peer_route_admission(
    service_p95_us_by_routes: &[f64],
    standalone_rtt_p95_us: f64,
    fanout_rtt_p95_us: f64,
    local_cold_p95_us_per_expert: f64,
    topk: usize,
) -> Vec<bool> {
    let effective_rtt_p95_us = standalone_rtt_p95_us.max(fanout_rtt_p95_us);
    (1..=topk)
        .map(|count| {
            effective_rtt_p95_us + service_p95_us_by_routes[count - 1]
                < local_cold_p95_us_per_expert * count as f64
        })
        .collect()
}

fn layer_split_sequence_state_contract(
    attn: &GpuAttnConfig,
    post_attn_norm_ptr: u64,
) -> Option<&'static str> {
    match attn {
        GpuAttnConfig::Mamba2 { .. } => Some("Mamba2 sequence-state"),
        GpuAttnConfig::GQA { num_heads: 0, .. } if post_attn_norm_ptr == 0 => {
            Some("attention-free sequence-state")
        }
        _ => None,
    }
}

fn check_peer_mode_prediction(graph: &mut GpuDecodeGraph, generated: usize, elapsed_seconds: f64) {
    if generated == 0 {
        return;
    }
    let Some(peer) = graph.peer_experts.first() else {
        return;
    };
    if peer.prediction_checked {
        return;
    }
    let predicted_peer_ms = peer.predicted_peer_ms_per_token;
    let alternative_ms = peer.alternative_ms_per_token;
    let uncertainty_ms = peer.selector_uncertainty_ms;
    for peer in &mut graph.peer_experts {
        peer.prediction_checked = true;
    }
    let actual_ms = elapsed_seconds / generated as f64 * 1_000.0;
    let (_, message) =
        peer_selector_check_message(actual_ms, predicted_peer_ms, alternative_ms, uncertainty_ms);
    eprintln!("{message}");
}

#[derive(Clone, Copy)]
struct PeerRoutedExpert {
    expert_idx: usize,
    weight: f32,
    batch_slot: usize,
}

struct PendingPeerDispatch {
    peer_index: usize,
    routes: Vec<PeerRoutedExpert>,
    started: std::time::Instant,
}

fn dynamic_peer_shard(
    layer_idx: usize,
    expert_idx: usize,
    experts_per_layer: usize,
    peer_count: usize,
) -> Option<usize> {
    if peer_count == 0 {
        return None;
    }
    Some(
        layer_idx
            .wrapping_mul(experts_per_layer.max(1))
            .wrapping_add(expert_idx)
            % peer_count,
    )
}

fn claimed_peer_route_slots(
    pending_peers: &[PendingPeerDispatch],
) -> Result<HashSet<usize>, String> {
    let mut claimed = HashSet::new();
    for pending in pending_peers {
        for route in &pending.routes {
            if !claimed.insert(route.batch_slot) {
                return Err(format!(
                    "multiple peers claimed routed slot {} (latest peer {})",
                    route.batch_slot, pending.peer_index,
                ));
            }
        }
    }
    Ok(claimed)
}

impl PeerExpertRuntime {
    fn host_request_ptr(&self) -> *mut u8 {
        unsafe { self.mailbox.host_ptr.add(PEER_MAILBOX_CONTROL_BYTES) }
    }

    fn host_response_ptr(&self, hidden_bytes: usize) -> *mut u8 {
        unsafe { self.host_request_ptr().add(hidden_bytes) }
    }

    fn primary_control_ptr(&self) -> u64 {
        self.mailbox.device_ptr
    }

    fn peer_control_ptr(&self) -> u64 {
        self.peer_mapping
    }

    fn peer_request_ptr(&self) -> u64 {
        self.peer_mapping + PEER_MAILBOX_CONTROL_BYTES as u64
    }
}

