fn validate_stream_probe_outcome(
    max_tokens: usize,
    generated: usize,
    stream_failure: Option<&str>,
) -> Result<(), String> {
    if max_tokens == 0 {
        return Err("decode calibration probe requires max_tokens > 0".to_string());
    }
    if let Some(failure) = stream_failure {
        return Err(format!("decode calibration probe failed: {}", failure));
    }
    if generated == 0 {
        return Err(
            "decode calibration probe generated zero tokens without reporting a native failure"
                .to_string(),
        );
    }
    Ok(())
}

#[derive(Clone, Copy, Debug)]
struct DeepseekV4DecodePolicy {
    hqq6_vec4: bool,
    hqq6_warp_autotune: bool,
    /// Explicit N32 selection. `None` means measure N16 versus N32 on the
    /// loaded routed-expert tensors before graph capture.
    int4_w13_n32: Option<bool>,
    int4_w2_n32: Option<bool>,
    index_radix_topk: bool,
    parallel_wkv: bool,
    parallel_qb: bool,
    hc_tiled: bool,
    marlin_autotune: bool,
    shared_w2_autotune: bool,
}

impl DeepseekV4DecodePolicy {
    fn from_env(deepseek_specific_default: bool) -> Result<Self, String> {
        let int4_w13_n32 = resolve_optional_bool_env("KRASIS_DECODE_INT4_W13_N32")?
            .or(deepseek_specific_default.then_some(true));
        let int4_w2_n32 = resolve_optional_bool_env("KRASIS_DECODE_INT4_W2_N32")?
            .or(deepseek_specific_default.then_some(true));
        let policy = Self {
            hqq6_vec4: resolve_bool_env("KRASIS_DECODE_V4_HQQ6_VEC4", deepseek_specific_default)?,
            hqq6_warp_autotune: resolve_bool_env(
                "KRASIS_DECODE_V4_HQQ6_WARP_AUTOTUNE",
                deepseek_specific_default,
            )?,
            int4_w13_n32,
            int4_w2_n32,
            index_radix_topk: resolve_bool_env("KRASIS_DECODE_V4_INDEX_RADIX_TOPK", false)?,
            parallel_wkv: resolve_bool_env(
                "KRASIS_DECODE_V4_PARALLEL_WKV",
                deepseek_specific_default,
            )?,
            parallel_qb: resolve_bool_env(
                "KRASIS_DECODE_V4_PARALLEL_QB",
                deepseek_specific_default,
            )?,
            hc_tiled: resolve_bool_env("KRASIS_DECODE_V4_HC_TILED", deepseek_specific_default)?,
            // These autotuners measure the loaded model's real shapes and
            // weights, and retain the formula/current kernel unless the
            // measured alternative clears the configured margin. They are
            // shared MoE policy, not DeepSeek-specific policy.
            marlin_autotune: resolve_bool_env("KRASIS_MARLIN_AUTOTUNE", true)?,
            shared_w2_autotune: resolve_bool_env("KRASIS_SHARED_W2_AUTOTUNE", true)?,
        };
        if policy.parallel_qb && !policy.parallel_wkv {
            return Err(
                "KRASIS_DECODE_V4_PARALLEL_QB requires KRASIS_DECODE_V4_PARALLEL_WKV".to_string(),
            );
        }
        Ok(policy)
    }
}

