    fn hqq_registration_json(&self, layer_idx: usize) -> PyResult<String> {
        let graph = self
            .graph
            .as_ref()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        let layer = graph.layers.get(layer_idx).ok_or_else(|| {
            pyo3::exceptions::PyRuntimeError::new_err(format!("Layer {} not registered", layer_idx))
        })?;
        let hqq = layer.hqq.as_ref().ok_or_else(|| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "Layer {} has no HQQ registration",
                layer_idx
            ))
        })?;

        let mut tensor_names: Vec<_> = hqq.tensors.keys().cloned().collect();
        tensor_names.sort();
        let tensors: Vec<_> = tensor_names
            .into_iter()
            .map(|name| {
                let desc = &hqq.tensors[&name];
                serde_json::json!({
                    "tensor_name": name,
                    "packed_ptr": desc.packed_ptr,
                    "scales_ptr": desc.scales_ptr,
                    "zeros_ptr": desc.zeros_ptr,
                    "orig_shape": [desc.rows, desc.cols],
                    "group_size": desc.group_size,
                    "axis": desc.axis,
                    "layout": desc.layout,
                    "packed_dtype": desc.packed_dtype,
                    "scales_dtype": desc.scales_dtype,
                    "zeros_dtype": desc.zeros_dtype,
                    "original_dtype": desc.original_dtype,
                    "tensor_bytes": desc.tensor_bytes,
                    "runtime_stage": desc.runtime_stage,
                    "runtime_kind": desc.runtime_kind,
                    "packed_row_stride_bytes": desc.packed_row_stride_bytes,
                    "scales_row_stride_bytes": desc.scales_row_stride_bytes,
                    "zeros_row_stride_bytes": desc.zeros_row_stride_bytes,
                    "rows_per_tile": desc.rows_per_tile,
                    "row_blocks": desc.row_blocks,
                    "kernel_ready": desc.kernel_ready,
                })
            })
            .collect();
        let metadata = match &hqq.metadata {
            HqqLayerMetadata::Gqa {
                num_heads,
                num_kv_heads,
                head_dim,
                rope_half_dim,
                rope_cos_ptr,
                rope_sin_ptr,
                sm_scale,
                q_norm_ptr,
                k_norm_ptr,
                gated,
                head_gate_proj,
            } => serde_json::json!({
                "kind": "gqa",
                "num_heads": num_heads,
                "num_kv_heads": num_kv_heads,
                "head_dim": head_dim,
                "rope_half_dim": rope_half_dim,
                "rope_cos_ptr": rope_cos_ptr,
                "rope_sin_ptr": rope_sin_ptr,
                "sm_scale": sm_scale,
                "q_norm_ptr": q_norm_ptr,
                "k_norm_ptr": k_norm_ptr,
                "gated": gated,
                "head_gate_proj": head_gate_proj,
            }),
            HqqLayerMetadata::Mla {
                num_heads,
                kv_lora_rank,
                ckv_cache_dim,
                qk_nope_dim,
                qk_rope_dim,
                v_head_dim,
                q_lora_rank,
                sm_scale,
                rope_interleave,
                kv_a_norm_ptr,
                w_kc_ptr,
                w_vc_ptr,
                ckv_cache_ptr,
                kpe_cache_ptr,
                q_a_norm_ptr,
            } => serde_json::json!({
                "kind": "mla",
                "num_heads": num_heads,
                "kv_lora_rank": kv_lora_rank,
                "ckv_cache_dim": ckv_cache_dim,
                "qk_nope_dim": qk_nope_dim,
                "qk_rope_dim": qk_rope_dim,
                "v_head_dim": v_head_dim,
                "q_lora_rank": q_lora_rank,
                "sm_scale": sm_scale,
                "rope_interleave": rope_interleave,
                "kv_a_norm_ptr": kv_a_norm_ptr,
                "w_kc_ptr": w_kc_ptr,
                "w_vc_ptr": w_vc_ptr,
                "ckv_cache_ptr": ckv_cache_ptr,
                "kpe_cache_ptr": kpe_cache_ptr,
                "q_a_norm_ptr": q_a_norm_ptr,
            }),
            HqqLayerMetadata::LinearAttention {
                num_k_heads,
                num_v_heads,
                k_head_dim,
                v_head_dim,
                head_ratio,
                kernel_dim,
                conv_dim,
                scale,
                conv_weight_ptr,
                a_log_ptr,
                dt_bias_ptr,
                norm_weight_ptr,
                conv_state_ptr,
                recur_state_ptr,
            } => serde_json::json!({
                "kind": "linear_attention",
                "num_k_heads": num_k_heads,
                "num_v_heads": num_v_heads,
                "k_head_dim": k_head_dim,
                "v_head_dim": v_head_dim,
                "head_ratio": head_ratio,
                "kernel_dim": kernel_dim,
                "conv_dim": conv_dim,
                "scale": scale,
                "conv_weight_ptr": conv_weight_ptr,
                "a_log_ptr": a_log_ptr,
                "dt_bias_ptr": dt_bias_ptr,
                "norm_weight_ptr": norm_weight_ptr,
                "conv_state_ptr": conv_state_ptr,
                "recur_state_ptr": recur_state_ptr,
            }),
            HqqLayerMetadata::KimiDeltaAttention {
                num_heads,
                head_dim,
                kernel_dim,
                gate_lower_bound,
                conv_weight_ptr,
                a_log_ptr,
                dt_bias_ptr,
                norm_weight_ptr,
                conv_state_ptr,
                recur_state_ptr,
            } => serde_json::json!({
                "kind": "kimi_delta_attention",
                "num_heads": num_heads,
                "head_dim": head_dim,
                "kernel_dim": kernel_dim,
                "gate_lower_bound": gate_lower_bound,
                "conv_weight_ptr": conv_weight_ptr,
                "a_log_ptr": a_log_ptr,
                "dt_bias_ptr": dt_bias_ptr,
                "norm_weight_ptr": norm_weight_ptr,
                "conv_state_ptr": conv_state_ptr,
                "recur_state_ptr": recur_state_ptr,
            }),
        };

        Ok(serde_json::json!({
            "layer_idx": layer_idx,
            "layer_kind": hqq.layer_kind,
            "backend": hqq.backend,
            "format_version": hqq.format_version,
            "nbits": hqq.nbits,
            "metadata": metadata,
            "input_norm_ptr": layer.input_norm_ptr,
            "input_norm_size": layer.input_norm_size,
            "post_attn_norm_ptr": layer.post_attn_norm_ptr,
            "post_attn_norm_size": layer.post_attn_norm_size,
            "tensor_count": tensors.len(),
            "tensors": tensors,
        })
        .to_string())
    }

    fn hqq_execution_json(&self, layer_idx: usize) -> PyResult<String> {
        let graph = self
            .graph
            .as_ref()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        let layer = graph.layers.get(layer_idx).ok_or_else(|| {
            pyo3::exceptions::PyRuntimeError::new_err(format!("Layer {} not registered", layer_idx))
        })?;
        if let Some(exec) = layer.hqq_exec.as_ref() {
            return Ok(hqq_execution_json_value(exec).to_string());
        }
        if let Some(v4) = layer.deepseek_v4.as_ref() {
            if !v4.hqq_tensors.is_empty() {
                let mut names: Vec<_> = v4.hqq_tensors.keys().cloned().collect();
                names.sort();
                let tensors: Vec<_> = names
                    .iter()
                    .map(|name| hqq_tensor_exec_json(&v4.hqq_tensors[name], name))
                    .collect();
                return Ok(serde_json::json!({
                    "kind": "deepseek_v4",
                    "tensors": tensors,
                })
                .to_string());
            }
        }
        Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
            "Layer {} has no HQQ execution descriptor",
            layer_idx
        )))
    }

    fn hqq_decode_timing_json(&self) -> PyResult<String> {
        Ok(serde_json::json!({
            "entries": self.hqq_decode_timing_entries.iter().map(|entry| {
                serde_json::json!({
                    "layer_idx": entry.layer_idx,
                    "token_id": entry.token_id,
                    "position": entry.position,
                    "tensor_name": entry.tensor_name,
                    "output_mode": entry.output_mode,
                    "duration_ms": entry.duration_ms,
                })
            }).collect::<Vec<_>>()
        })
        .to_string())
    }

    fn debug_run_hqq_decode_gemv_f32(
        &mut self,
        layer_idx: usize,
        tensor_name: &str,
        input_ptr: usize,
    ) -> PyResult<Vec<f32>> {
        self.device.bind_to_thread().map_err(|e| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "debug_run_hqq_decode_gemv_f32 bind_to_thread: {:?}",
                e
            ))
        })?;
        let desc = self
            .hqq_runtime_decode_exec_desc_for_tensor(layer_idx, tensor_name)
            .map_err(pyo3::exceptions::PyRuntimeError::new_err)?;
        let output = self.device.alloc_zeros::<f32>(desc.rows).map_err(|e| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "debug_run_hqq_decode_gemv_f32 alloc output: {:?}",
                e
            ))
        })?;
        self.launch_hqq_decode_gemv_f32(tensor_name, &desc, input_ptr as u64, *output.device_ptr())
            .map_err(pyo3::exceptions::PyRuntimeError::new_err)?;
        self.device.synchronize().map_err(|e| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "debug_run_hqq_decode_gemv_f32 sync: {:?}",
                e
            ))
        })?;
        self.download_device_f32(*output.device_ptr(), desc.rows)
            .map_err(pyo3::exceptions::PyRuntimeError::new_err)
    }

    fn debug_run_hqq_decode_gemv_bf16(
        &mut self,
        layer_idx: usize,
        tensor_name: &str,
        input_ptr: usize,
    ) -> PyResult<Vec<f32>> {
        self.device.bind_to_thread().map_err(|e| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "debug_run_hqq_decode_gemv_bf16 bind_to_thread: {:?}",
                e
            ))
        })?;
        let desc = self
            .hqq_runtime_decode_exec_desc_for_tensor(layer_idx, tensor_name)
            .map_err(pyo3::exceptions::PyRuntimeError::new_err)?;
        let output = self.device.alloc_zeros::<u16>(desc.rows).map_err(|e| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "debug_run_hqq_decode_gemv_bf16 alloc output: {:?}",
                e
            ))
        })?;
        self.launch_hqq_decode_gemv_bf16(
            tensor_name,
            &desc,
            input_ptr as u64,
            *output.device_ptr(),
        )
        .map_err(pyo3::exceptions::PyRuntimeError::new_err)?;
        self.device.synchronize().map_err(|e| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "debug_run_hqq_decode_gemv_bf16 sync: {:?}",
                e
            ))
        })?;
        self.download_device_bf16_as_f32(*output.device_ptr(), desc.rows)
            .map_err(pyo3::exceptions::PyRuntimeError::new_err)
    }

    fn hqq_prefill_descriptor_json(&self, layer_idx: usize) -> PyResult<String> {
        let engine = self.prefill_engine_slot.as_ref().ok_or_else(|| {
            pyo3::exceptions::PyRuntimeError::new_err("Prefill engine not allocated yet")
        })?;
        let layer = engine.layer_weights.get(layer_idx).ok_or_else(|| {
            pyo3::exceptions::PyRuntimeError::new_err(format!(
                "Prefill layer {} not available",
                layer_idx
            ))
        })?;
        let payload = if let Some(desc) = &layer.hqq_gqa {
            serde_json::json!({
                "layer_kind": "gqa",
                "backend": desc.backend,
                "format_version": desc.format_version,
                "nbits": desc.nbits,
                "metadata": {
                    "num_heads": desc.num_heads,
                    "num_kv_heads": desc.num_kv_heads,
                    "head_dim": desc.head_dim,
                    "sm_scale": desc.sm_scale,
                    "q_norm_ptr": desc.q_norm_ptr,
                    "k_norm_ptr": desc.k_norm_ptr,
                    "gated": desc.gated,
                },
                "tensors": [
                    hqq_prefill_tensor_exec_json(&desc.q_proj, "q_proj"),
                    hqq_prefill_tensor_exec_json(&desc.k_proj, "k_proj"),
                    hqq_prefill_tensor_exec_json(&desc.v_proj, "v_proj"),
                    hqq_prefill_tensor_exec_json(&desc.o_proj, "o_proj"),
                ],
            })
        } else if let Some(desc) = &layer.mla_prefill {
            fn hqq_projection(
                projection: &crate::gpu_prefill::DeepseekV4ProjectionPrefillDescriptor,
                layer_idx: usize,
            ) -> PyResult<&crate::gpu_prefill::HqqTensorExecDescriptor> {
                match projection {
                    crate::gpu_prefill::DeepseekV4ProjectionPrefillDescriptor::Hqq {
                        desc, ..
                    } => Ok(desc),
                    crate::gpu_prefill::DeepseekV4ProjectionPrefillDescriptor::Bf16(_) => {
                        Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                            "Prefill layer {} uses native BF16 MLA, not an HQQ descriptor",
                            layer_idx
                        )))
                    }
                }
            }
            let backend = desc.hqq_backend.as_ref().ok_or_else(|| {
                pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "Prefill layer {} uses native BF16 MLA, not an HQQ descriptor",
                    layer_idx
                ))
            })?;
            let mut tensors = vec![
                hqq_prefill_tensor_exec_json(
                    hqq_projection(&desc.kv_a_proj_with_mqa, layer_idx)?,
                    "kv_a_proj_with_mqa",
                ),
                hqq_prefill_tensor_exec_json(hqq_projection(&desc.o_proj, layer_idx)?, "o_proj"),
            ];
            if let Some(q_a_proj) = &desc.q_a_proj {
                tensors.push(hqq_prefill_tensor_exec_json(
                    hqq_projection(q_a_proj, layer_idx)?,
                    "q_a_proj",
                ));
            }
            if let Some(q_b_proj) = &desc.q_b_proj {
                tensors.push(hqq_prefill_tensor_exec_json(
                    hqq_projection(q_b_proj, layer_idx)?,
                    "q_b_proj",
                ));
            }
            if let Some(q_proj) = &desc.q_proj {
                tensors.push(hqq_prefill_tensor_exec_json(
                    hqq_projection(q_proj, layer_idx)?,
                    "q_proj",
                ));
            }
            serde_json::json!({
                "layer_kind": "mla",
                "backend": backend,
                "format_version": desc.hqq_format_version,
                "nbits": desc.hqq_nbits,
                "metadata": {
                    "num_heads": desc.num_heads,
                    "kv_lora_rank": desc.kv_lora_rank,
                    "ckv_cache_dim": desc.ckv_cache_dim,
                    "qk_nope_dim": desc.qk_nope_dim,
                    "qk_rope_dim": desc.qk_rope_dim,
                    "v_head_dim": desc.v_head_dim,
                    "q_lora_rank": desc.q_lora_rank,
                    "sm_scale": desc.sm_scale,
                    "rope_interleave": desc.rope_interleave,
                    "kv_a_norm_ptr": desc.kv_a_norm_ptr,
                    "w_kc_ptr": desc.w_kc_ptr,
                    "w_vc_ptr": desc.w_vc_ptr,
                    "ckv_cache_ptr": desc.ckv_cache_ptr,
                    "kpe_cache_ptr": desc.kpe_cache_ptr,
                    "q_a_norm_ptr": desc.q_a_norm_ptr,
                },
                "tensors": tensors,
            })
        } else if let Some(desc) = &layer.hqq_linear_attention {
            serde_json::json!({
                "layer_kind": "linear_attention",
                "backend": desc.backend,
                "format_version": desc.format_version,
                "nbits": desc.nbits,
                "metadata": {
                    "num_k_heads": desc.num_k_heads,
                    "num_v_heads": desc.num_v_heads,
                    "k_head_dim": desc.k_head_dim,
                    "v_head_dim": desc.v_head_dim,
                    "head_ratio": desc.head_ratio,
                    "kernel_dim": desc.kernel_dim,
                    "conv_dim": desc.conv_dim,
                    "scale": desc.scale,
                    "conv_weight_ptr": desc.conv_weight_ptr,
                    "a_log_ptr": desc.a_log_ptr,
                    "dt_bias_ptr": desc.dt_bias_ptr,
                    "norm_weight_ptr": desc.norm_weight_ptr,
                    "conv_state_ptr": desc.conv_state_ptr,
                    "recur_state_ptr": desc.recur_state_ptr,
                },
                "tensors": [
                    hqq_prefill_tensor_exec_json(&desc.in_proj_qkvz, "in_proj_qkvz"),
                    hqq_prefill_tensor_exec_json(&desc.in_proj_ba, "in_proj_ba"),
                    hqq_prefill_tensor_exec_json(&desc.out_proj, "out_proj"),
                ],
            })
        } else {
            return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                "Prefill layer {} has no HQQ execution descriptor",
                layer_idx
            )));
        };
        Ok(payload.to_string())
    }

    #[pyo3(signature = (layer_idx, hidden_bf16, m, start_pos=0, capture_kv_cache=false))]
    fn debug_run_gqa_prefill_layer(
        &mut self,
        layer_idx: usize,
        hidden_bf16: Vec<u16>,
        m: usize,
        start_pos: usize,
        capture_kv_cache: bool,
    ) -> PyResult<Vec<u16>> {
        let engine = self.prefill_engine_slot.as_mut().ok_or_else(|| {
            pyo3::exceptions::PyRuntimeError::new_err("Prefill engine not allocated yet")
        })?;
        engine
            .debug_run_gqa_prefill_layer(layer_idx, &hidden_bf16, m, start_pos, capture_kv_cache)
            .map_err(pyo3::exceptions::PyRuntimeError::new_err)
    }

    fn decode_timing_json(&self) -> PyResult<String> {
        let graph = self
            .graph
            .as_ref()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        Ok(serde_json::json!({
            "timing_enabled": graph.timing_enabled,
            "timing_step_count": graph.timing_step_count,
            "t_total_s": graph.t_total,
            "t_attn_gqa_s": graph.t_attn_gqa,
            "t_gqa_proj_s": graph.t_gqa_proj,
            "t_gqa_attn_s": graph.t_gqa_attn,
            "t_gqa_out_s": graph.t_gqa_out,
        })
        .to_string())
    }

    /// Set Mamba2 n_groups parameter (shared across all Mamba2 layers).
    fn set_mamba2_n_groups(&mut self, n_groups: usize) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        graph.mamba2_n_groups = n_groups;
        log::info!("GpuDecodeStore: set mamba2_n_groups={}", n_groups);
        Ok(())
    }

    /// Set Mamba2 SSD chunk size from model config.
    fn set_mamba2_chunk_size(&mut self, chunk_size: usize) -> PyResult<()> {
        if chunk_size == 0 {
            return Err(pyo3::exceptions::PyValueError::new_err(
                "Mamba2 chunk_size must be non-zero",
            ));
        }
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        graph.mamba2_chunk_size = chunk_size;
        log::info!("GpuDecodeStore: set mamba2_chunk_size={}", chunk_size);
        Ok(())
    }

    /// Register conv bias pointer for a Mamba2 layer (FP32 on GPU).
    fn set_mamba2_conv_bias(&mut self, layer_idx: usize, conv_bias_ptr: usize) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        graph
            .mamba2_conv_bias_ptrs
            .insert(layer_idx, conv_bias_ptr as u64);
        Ok(())
    }

    /// Register MLP config for a layer (MoE, Dense, or None).
    /// For MoE layers, the expert data should already be registered via register_moe_layer.
    #[pyo3(signature = (
        layer_idx, mlp_type, gate_proj_wid=None, up_proj_wid=None,
        down_proj_wid=None, swiglu_limit=0.0, deepseek_clamp=false
    ))]
    fn register_mlp(
        &mut self,
        layer_idx: usize,
        mlp_type: &str,
        gate_proj_wid: Option<usize>,
        up_proj_wid: Option<usize>,
        down_proj_wid: Option<usize>,
        swiglu_limit: f32,
        deepseek_clamp: bool,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        if layer_idx >= graph.layers.len() {
            return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                "Layer {} not registered",
                layer_idx
            )));
        }
        if !swiglu_limit.is_finite() || swiglu_limit < 0.0 {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "Dense SwiGLU limit must be finite and non-negative, got {}",
                swiglu_limit
            )));
        }
        if deepseek_clamp && swiglu_limit <= 0.0 {
            return Err(pyo3::exceptions::PyValueError::new_err(
                "DeepSeek/GLM dense SwiGLU clamp requires a positive limit",
            ));
        }
        match mlp_type {
            "moe" => {
                // MoE config is read from graph.moe_layers during decode_step
                graph.layers[layer_idx].mlp = GpuMlpConfig::None; // Placeholder; MoE data is in moe_layers
            }
            "dense" => {
                graph.layers[layer_idx].dense_swiglu_limit = swiglu_limit;
                graph.layers[layer_idx].dense_deepseek_clamp = deepseek_clamp;
                graph.layers[layer_idx].mlp = GpuMlpConfig::Dense {
                    gate_proj: gate_proj_wid.ok_or_else(|| {
                        pyo3::exceptions::PyValueError::new_err("gate_proj_wid required")
                    })?,
                    up_proj: up_proj_wid.ok_or_else(|| {
                        pyo3::exceptions::PyValueError::new_err("up_proj_wid required")
                    })?,
                    down_proj: down_proj_wid.ok_or_else(|| {
                        pyo3::exceptions::PyValueError::new_err("down_proj_wid required")
                    })?,
                };
            }
            _ => {
                graph.layers[layer_idx].mlp = GpuMlpConfig::None;
            }
        }
        Ok(())
    }

    /// Register Gemma4's text-layer MLP shape: every layer has a dense branch
    /// and a routed MoE branch, plus branch-specific norms.
    #[pyo3(signature = (
        layer_idx,
        dense_gate_proj_wid,
        dense_up_proj_wid,
        dense_down_proj_wid,
        pre_ffn_norm_ptr=0,
        post_ffn_norm_ptr=0,
        post_ffn_norm1_ptr=0,
        post_ffn_norm2_ptr=0,
        pre_ffn_norm2_ptr=0,
        layer_scalar_ptr=0,
        router_input_scale_ptr=0,
        router_per_expert_scale_ptr=0
    ))]
    #[allow(clippy::too_many_arguments)]
    fn register_gemma4_moe_layer(
        &mut self,
        layer_idx: usize,
        dense_gate_proj_wid: usize,
        dense_up_proj_wid: usize,
        dense_down_proj_wid: usize,
        pre_ffn_norm_ptr: usize,
        post_ffn_norm_ptr: usize,
        post_ffn_norm1_ptr: usize,
        post_ffn_norm2_ptr: usize,
        pre_ffn_norm2_ptr: usize,
        layer_scalar_ptr: usize,
        router_input_scale_ptr: usize,
        router_per_expert_scale_ptr: usize,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        if layer_idx >= graph.layers.len() {
            return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                "Layer {} not registered",
                layer_idx
            )));
        }
        let layer = &mut graph.layers[layer_idx];
        layer.pre_ffn_norm_ptr = pre_ffn_norm_ptr as u64;
        layer.post_ffn_norm_ptr = post_ffn_norm_ptr as u64;
        layer.post_ffn_norm1_ptr = post_ffn_norm1_ptr as u64;
        layer.post_ffn_norm2_ptr = post_ffn_norm2_ptr as u64;
        layer.pre_ffn_norm2_ptr = pre_ffn_norm2_ptr as u64;
        layer.layer_scalar_ptr = layer_scalar_ptr as u64;
        layer.router_input_scale_ptr = router_input_scale_ptr as u64;
        layer.router_per_expert_scale_ptr = router_per_expert_scale_ptr as u64;
        layer.mlp = GpuMlpConfig::Gemma4MoE {
            dense_gate_proj: dense_gate_proj_wid,
            dense_up_proj: dense_up_proj_wid,
            dense_down_proj: dense_down_proj_wid,
        };
        Ok(())
    }

    /// Set up RoPE tables in VRAM for GQA attention.
    /// cos_ptr, sin_ptr: device pointers to FP32 [max_seq, half_dim] on GPU.
    #[pyo3(signature = (cos_ptr, sin_ptr, half_dim, max_seq))]
    fn set_rope_tables(
        &mut self,
        cos_ptr: usize,
        sin_ptr: usize,
        half_dim: usize,
        max_seq: usize,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        // Copy from the PyTorch tensors into our own VRAM allocations
        let total = max_seq * half_dim;
        let d_cos = self
            .device
            .alloc_zeros::<f32>(total)
            .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?;
        let d_sin = self
            .device
            .alloc_zeros::<f32>(total)
            .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?;
        // D2D copy
        unsafe {
            let err =
                cuda_sys::lib().cuMemcpyDtoD_v2(*d_cos.device_ptr(), cos_ptr as u64, total * 4);
            if err != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "D2D rope cos: {:?}",
                    err
                )));
            }
            let err =
                cuda_sys::lib().cuMemcpyDtoD_v2(*d_sin.device_ptr(), sin_ptr as u64, total * 4);
            if err != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "D2D rope sin: {:?}",
                    err
                )));
            }
        }
        graph.d_rope_cos = Some(d_cos);
        graph.d_rope_sin = Some(d_sin);
        graph.rope_half_dim = half_dim;
        log::info!(
            "GpuDecodeStore: RoPE tables set ({} half_dim, {} max_seq)",
            half_dim,
            max_seq
        );
        Ok(())
    }

    pub fn set_rope_position_delta(&mut self, delta: i32) {
        if let Some(ref mut graph) = self.graph {
            graph.rope_position_delta = delta;
        }
    }

    /// Register shared FP8 KV cache pointers from Python's PagedKVCache.
    /// Python owns the memory (FP8 E4M3 contiguous tensors). Both Rust
    /// prefill and Rust decode read/write the same buffers — no export copy.
    ///
    /// kv_ptrs: list of (layer_idx, k_data_ptr, v_data_ptr) device pointers.
    /// max_seq: maximum sequence length the buffers can hold.
    #[pyo3(signature = (kv_ptrs, max_seq))]
    fn set_kv_cache_ptrs(
        &mut self,
        kv_ptrs: Vec<(usize, usize, usize)>,
        max_seq: usize,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        let num_layers = graph.layers.len();
        graph.kv_k_ptrs = vec![0u64; num_layers];
        graph.kv_v_ptrs = vec![0u64; num_layers];
        graph.kv_max_seq = max_seq;
        graph.kv_max_seq_by_layer = vec![max_seq; num_layers];
        let mut registered = 0usize;
        for (layer_idx, k_ptr, v_ptr) in kv_ptrs {
            if layer_idx >= num_layers {
                return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "Layer {} out of range ({})",
                    layer_idx, num_layers
                )));
            }
            graph.kv_k_ptrs[layer_idx] = k_ptr as u64;
            graph.kv_v_ptrs[layer_idx] = v_ptr as u64;
            registered += 1;
        }
        log::info!(
            "GpuDecodeStore: KV cache shared FP8 pointers set ({} GQA layers, max_seq={})",
            registered,
            max_seq
        );

        // Allocate FlashDecoding tiled attention buffers.
        // Find max num_q_heads and head_dim across all GQA layers.
        let mut max_nh: usize = 0;
        let mut max_hd: usize = 0;
        for layer in &graph.layers {
            if let GpuAttnConfig::GQA {
                num_heads,
                head_dim,
                ..
            } = &layer.attn
            {
                max_nh = max_nh.max(*num_heads);
                max_hd = max_hd.max(*head_dim);
            }
        }
        if max_nh > 0 && max_hd > 0 {
            let tile_size: usize = 256;
            let max_tiles = (max_seq + tile_size - 1) / tile_size;
            let partial_o_size = max_nh * max_tiles * max_hd; // floats
            let partial_lse_size = max_nh * max_tiles * 2; // floats
            let d_tiled_o = self
                .device
                .alloc_zeros::<f32>(partial_o_size)
                .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?;
            let d_tiled_lse = self
                .device
                .alloc_zeros::<f32>(partial_lse_size)
                .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?;
            let o_mb = (partial_o_size * 4) as f64 / (1024.0 * 1024.0);
            let lse_kb = (partial_lse_size * 4) as f64 / 1024.0;
            log::info!(
                "GpuDecodeStore: tiled GQA buffers allocated (tile_size={}, max_tiles={}, \
                        partial_o={:.1} MB, partial_lse={:.1} KB)",
                tile_size,
                max_tiles,
                o_mb,
                lse_kb
            );
            graph.d_gqa_tiled_o = Some(d_tiled_o);
            graph.d_gqa_tiled_lse = Some(d_tiled_lse);
            graph.gqa_tile_size = tile_size;
            graph.gqa_max_tiles = max_tiles;
            graph.gqa_num_q_heads = max_nh;
            graph.gqa_head_dim = max_hd;
        }

        Ok(())
    }

    /// Finalize native compact MLA cache registration after every MLA layer
    /// has provided its own compressed/positional cache pointers. Unlike the
    /// GQA setters, this method does not invent shared K/V pointer arrays: MLA
    /// owns its cache pointers in each layer descriptor.
    #[pyo3(signature = (kv_format, max_seq))]
    fn set_native_mla_kv_cache(&mut self, kv_format: u32, max_seq: usize) -> PyResult<()> {
        if !matches!(kv_format, 7 | 9) {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "Native MLA cache requires k4v4 (9) or k6v6 (7), got format {}",
                kv_format
            )));
        }
        if max_seq == 0 {
            return Err(pyo3::exceptions::PyValueError::new_err(
                "Native MLA cache max_seq must be positive",
            ));
        }
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;

        let mut mla_layers = 0usize;
        for (layer_idx, layer) in graph.layers.iter().enumerate() {
            if let GpuAttnConfig::MLA {
                qk_rope_dim,
                ckv_cache_ptr,
                kpe_cache_ptr,
                ..
            } = &layer.attn
            {
                if *ckv_cache_ptr == 0 || (*qk_rope_dim > 0 && *kpe_cache_ptr == 0) {
                    return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                        "Native MLA layer {} has incomplete compact cache pointers: ckv=0x{:x} kpe=0x{:x} rope_dim={}",
                        layer_idx, ckv_cache_ptr, kpe_cache_ptr, qk_rope_dim
                    )));
                }
                mla_layers += 1;
            }
        }
        if mla_layers == 0 {
            return Err(pyo3::exceptions::PyRuntimeError::new_err(
                "Native MLA cache registration found no MLA layers",
            ));
        }

        let num_layers = graph.layers.len();
        graph.kv_k_ptrs = vec![0u64; num_layers];
        graph.kv_v_ptrs = vec![0u64; num_layers];
        graph.kv_k_radius_ptrs = vec![0u64; num_layers];
        graph.kv_v_radius_ptrs = vec![0u64; num_layers];
        graph.kv_k_angles_ptrs = vec![0u64; num_layers];
        graph.kv_v_angles_ptrs = vec![0u64; num_layers];
        graph.kv_tq4_sign_ptrs = vec![0u64; num_layers];
        graph.kv_max_seq = max_seq;
        graph.kv_max_seq_by_layer = vec![max_seq; num_layers];
        graph.kv_format = kv_format;
        graph.kv_num_blocks = 0;
        graph.refresh_kv_blocks_by_layer();
        log::info!(
            "GpuDecodeStore: native MLA {} cache finalized ({} MLA layers, max_seq={})",
            if kv_format == 7 { "k6v6" } else { "k4v4" },
            mla_layers,
            max_seq
        );
        Ok(())
    }

    #[pyo3(signature = (max_seq_by_layer))]
    fn set_kv_cache_max_seq_by_layer(
        &mut self,
        max_seq_by_layer: Vec<(usize, usize)>,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        let num_layers = graph.layers.len();
        let mut values = vec![graph.kv_max_seq; num_layers];
        let mut registered = 0usize;
        for (layer_idx, max_seq) in max_seq_by_layer {
            if layer_idx >= num_layers {
                return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "Layer {} out of range ({})",
                    layer_idx, num_layers
                )));
            }
            if max_seq == 0 {
                return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "Layer {} has zero KV max_seq",
                    layer_idx
                )));
            }
            values[layer_idx] = max_seq;
            registered += 1;
        }
        graph.kv_max_seq_by_layer = values;
        let ring_layers = graph
            .kv_max_seq_by_layer
            .iter()
            .filter(|&&n| n > 0 && n < graph.kv_max_seq)
            .count();
        log::info!(
            "GpuDecodeStore: per-layer KV max_seq set ({} registered, {} ring-window layers, global max_seq={})",
            registered,
            ring_layers,
            graph.kv_max_seq
        );
        Ok(())
    }

    /// Register Polar4 KV cache pointers from Python's PagedKVCache.
    /// polar4_ptrs: list of (layer_idx, k_radius_ptr, v_radius_ptr, k_angles_ptr, v_angles_ptr)
    #[pyo3(signature = (polar4_ptrs, max_seq, num_blocks))]
    fn set_kv_cache_ptrs_polar4(
        &mut self,
        polar4_ptrs: Vec<(usize, usize, usize, usize, usize)>,
        max_seq: usize,
        num_blocks: usize,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        let num_layers = graph.layers.len();
        graph.kv_k_radius_ptrs = vec![0u64; num_layers];
        graph.kv_v_radius_ptrs = vec![0u64; num_layers];
        graph.kv_k_angles_ptrs = vec![0u64; num_layers];
        graph.kv_v_angles_ptrs = vec![0u64; num_layers];
        graph.kv_tq4_sign_ptrs = vec![0u64; num_layers];
        graph.kv_k_ptrs = vec![0u64; num_layers]; // clear FP8 ptrs
        graph.kv_v_ptrs = vec![0u64; num_layers];
        graph.kv_max_seq = max_seq;
        graph.kv_max_seq_by_layer = vec![max_seq; num_layers];
        graph.kv_format = 2;
        graph.kv_num_blocks = num_blocks;
        graph.refresh_kv_blocks_by_layer();
        let mut registered = 0usize;
        for (layer_idx, kr_ptr, vr_ptr, ka_ptr, va_ptr) in polar4_ptrs {
            if layer_idx >= num_layers {
                return Err(pyo3::exceptions::PyRuntimeError::new_err(format!(
                    "Layer {} out of range ({})",
                    layer_idx, num_layers
                )));
            }
            graph.kv_k_radius_ptrs[layer_idx] = kr_ptr as u64;
            graph.kv_v_radius_ptrs[layer_idx] = vr_ptr as u64;
            graph.kv_k_angles_ptrs[layer_idx] = ka_ptr as u64;
            graph.kv_v_angles_ptrs[layer_idx] = va_ptr as u64;
            registered += 1;
        }
        log::info!(
            "GpuDecodeStore: Polar4 KV cache pointers set ({} GQA layers, max_seq={}, blocks={}, norm_correction_mode={})",
            registered, max_seq, num_blocks, graph.polar4_norm_correction_mode
        );

        // Allocate FlashDecoding tiled attention buffers (same as FP8 path).
        let mut max_nh: usize = 0;
        let mut max_hd: usize = 0;
        for layer in &graph.layers {
            if let GpuAttnConfig::GQA {
                num_heads,
                head_dim,
                ..
            } = &layer.attn
            {
                max_nh = max_nh.max(*num_heads);
                max_hd = max_hd.max(*head_dim);
            }
        }
        if max_nh > 0 && max_hd > 0 {
            let tile_size: usize = 256;
            let max_tiles = (max_seq + tile_size - 1) / tile_size;
            let partial_o_size = max_nh * max_tiles * max_hd;
            let partial_lse_size = max_nh * max_tiles * 2;
            let d_tiled_o = self
                .device
                .alloc_zeros::<f32>(partial_o_size)
                .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?;
            let d_tiled_lse = self
                .device
                .alloc_zeros::<f32>(partial_lse_size)
                .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?;
            graph.d_gqa_tiled_o = Some(d_tiled_o);
            graph.d_gqa_tiled_lse = Some(d_tiled_lse);
            graph.gqa_tile_size = tile_size;
            graph.gqa_max_tiles = max_tiles;
            graph.gqa_num_q_heads = max_nh;
            graph.gqa_head_dim = max_hd;
        }
        if graph.d_graph_seq_len.is_none() {
            graph.d_graph_seq_len = Some(
                self.device
                    .alloc_zeros::<i32>(1)
                    .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("{:?}", e)))?,
            );
        }
        Ok(())
    }

