                g.t_gqa_proj = 0.0;
                g.t_gqa_attn = 0.0;
                g.t_gqa_out = 0.0;
                g.t_expert_w13 = 0.0;
                g.t_expert_silu_w2 = 0.0;
                g.t_dma_expert_wait = 0.0;
